---GetUnlockDescr
---获取解锁条件的文字
---@param unlockType Constants.CommonUnlockType @ 解锁条件
---@param unlockTargetNumStr string @ 填充targetnum的文字
---@return string
function GameUtils.GetUnlockDescr(unlockType, unlockTargetNumStr, unlockId)
    unlockType = checkInt(unlockType)
    unlockId = checkInt(unlockId)
    local descr = ""
    ---@type TableML.TableFile
    local setting = CS.Engine.Modules.SettingModule.Get(AutoIds.IdSetting3)
    local vo = setting:GetByPrimaryKey(unlockType)
    if isNull(vo) then
        return localize("未找到解锁条件_type_", { _type_ = checkString(unlockType) })
    end
    xTry(function()
        if unlockType == Constants.CommonUnlockType.PlayerLevel and checkInt(unlockTargetNumStr) == MAGIC_PLAYER_LEVEL then
            ---用户等级解锁的情况下
            descr = localize('敬请期待')
            return descr
        end
        descr = ParseLocalizeText(vo, "unlockCondition")
        if checkInt(unlockType) == Constants.CommonUnlockType.PassChapter then
            ---@type QuestMainChapterNodeVo
            local vo = QuestConfMgr:GetInstance():GetChapterVoByID(unlockTargetNumStr)
            if vo then
                descr = string.gsub(descr, "_target_num_", vo.name)
            else
                descr = string.gsub(descr, "_target_num_", string.format('<%s in ChapterVo is null>', tostring(unlockTargetNumStr)))
            end
        elseif checkInt(unlockType) == Constants.CommonUnlockType.PassQuest then
            ---@type QuestMainVo
            local questVo = QuestConfMgr:GetInstance():GetQuestVoById(unlockTargetNumStr)
            if questVo then
                local questType = GoodsUtils.GetIdType(questVo.id, Constants.IDArea.Quests)
                if questType == Constants.IDType.QuestMainChallenge then
                    ---因难本
                    local info = localize('通关主线挑战模式_target_num_')
                    descr = string.gsub(info, "_target_num_", string.format('%s%s', "", questVo.label))
                else
                    descr = string.gsub(descr, "_target_num_", string.format('%s%s', "", questVo.label))
                end
            else
                descr = string.gsub(descr, "_target_num_", string.format('<%s in QuestVo is null>', tostring(unlockTargetNumStr)))
            end
            --elseif checkInt(unlockType) == Constants.CommonUnlockType.MonthCard then
            --    descr =
        elseif checkInt(unlockType) == Constants.CommonUnlockType.PassChallengeQuest then
            local questVo = QuestConfMgr:GetInstance():GetQuestVoById(unlockTargetNumStr)
            if questVo then
                ---因难本
                descr = string.gsub(descr, "_target_num_", string.format('%s%s', "", questVo.label))
            end
        elseif checkInt(unlockType) == Constants.CommonUnlockType.PTActivity then
            --pt 活动填在一张表里
            local BambooUtils = import('Game.UI.FightReady.UIBamboo.BambooUtils')
            local bambooVo = BambooUtils.GetBambooActivityCopyVo(unlockTargetNumStr)
