                --好感度
                descr = localize("_name_好感度达到_num_级解锁", { _name_ = vo.name, _num_ = checkString(unlockTargetNumStr) })
            end
            --获取角色
        elseif checkInt(unlockType) == Constants.CommonUnlockType.GetRole then
            local vo = CardConfMgr:GetInstance():GetRolesByCharacterType(unlockId)
            if vo then
                descr = string.fmt(descr, { _target_num_ = vo.name })
            end
        elseif checkInt(unlockType) == Constants.CommonUnlockType.CatHouseCatType then
            --猫种
            local vo = CfUtils.GetCfVo(AutoIds.IdSetting1906, "CatHouseCatVo", unlockTargetNumStr)
            if vo then
                descr = string.gsub(descr, "_target_num_", vo.name)
            end
        elseif checkInt(unlockType) == Constants.CommonUnlockType.CatHouseCatGene then
            --基因
            local vo = CfUtils.GetCfVo(AutoIds.IdSetting1902, "CatHouseCatDataVo", unlockTargetNumStr)
            if vo then
                descr = string.gsub(descr, "_target_num_", vo.name)
            end
        elseif checkInt(unlockType) == Constants.CommonUnlockType.RegionLikability then
            local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
            local vo = ActionUtils.GetRegionPrimaryMapVo(unlockId)
            if vo then
                descr = localize("_name_好感度达到Lv._num_级解锁", { _name_ = vo.name, _num_ = checkString(unlockTargetNumStr) })
            end
        elseif checkInt(unlockType) == Constants.CommonUnlockType.RegionQuest then
            local vo = QuestConfMgr:GetInstance():GetQuestVoById(unlockTargetNumStr)
            if vo then
                descr = localize("通关区域_name_解锁", { _name_ = vo.name })
            end
        elseif checkInt(unlockType) == Constants.CommonUnlockType.RegionQuestUnlock then
            local vo = QuestConfMgr:GetInstance():GetQuestVoById(unlockTargetNumStr)
            if vo then
                descr = localize("区域关卡_name_开放后解锁", { _name_ = vo.name })
            end
        elseif checkInt(unlockType) == Constants.CommonUnlockType.MainQuestTask then
            local questVo = QuestConfMgr:GetInstance():GetQuestVoById(unlockTargetNumStr)
            if questVo then
                descr = string.gsub(descr, "_target_num_", questVo.label)
            end
        elseif checkInt(unlockType) == Constants.CommonUnlockType.QualityCards then
