        elseif checkInt(unlockType) == Constants.CommonUnlockType.GetFish then
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(unlockId)
            local targetNum = checkInt(unlockTargetNumStr)
            if targetNum <= 0 then
                descr = localize("钓起_fishName_后解锁", { _fishName_ = goodsVo.name })
            else
                descr = localize("钓起_fishNum_条_fishName_后解锁", { _fishName_ = goodsVo.name, _fishNum_ = targetNum })
            end
        elseif checkInt(unlockType) == Constants.CommonUnlockType.GetCard then
            local cardVo = CardConfMgr:GetInstance():GetCardByRefId(unlockTargetNumStr)
            descr = string.gsub(descr, "_target_num_", cardVo.name)
