        end
    end)
    return descr
end

---GetUnlockDescription
---获取解锁条件的全描述
---@param unlockTypes string
---@param unlockNumStr string
function GameUtils.GetUnlockDescription(unlockTypes, unlockNumStr, unlockIdStr)
    local str = ''
    if not unlockTypes or not unlockNumStr then
        return str
    end

    unlockIdStr = checkString(unlockIdStr)
    local unlockType = string.split2(unlockTypes, ";")
    local unlockNum = string.split2(unlockNumStr, ";")
    local unlockId = string.split2(unlockIdStr, ";")
    local length = math.min(#unlockType, #unlockNum)
    if length > 0 then
        local t = {}
        for i = 1, length do
            local unlockTargetType = checkInt(unlockType[i])
            local unlockTargetNum = checkInt(unlockNum[i])
            local unlockTargetId = checkInt(unlockId[i])
            if unlockTargetType > 0 then
                table.insert(t, GameUtils.GetUnlockDescr(unlockTargetType, unlockTargetNum, unlockTargetId))
            end
        end
        str = table.concat(t, '\n')
    end
    return str
end

---IsUnlocked
---@param unlockTypes string 解锁类型
---@param unlockNumStr string
---@param unlockIds string    --判断解锁条件的目标id
function GameUtils.IsUnlocked(unlockTypes, unlockNumStr, unlockIds)
    --没有为true
    if not unlockTypes or not unlockNumStr then
        return true
    end
    unlockTypes = checkString(unlockTypes)
    unlockNumStr = checkString(unlockNumStr)
    unlockIds = checkString(unlockIds)
    local unlockType = string.split2(unlockTypes, ";")
    local unlockNum = string.split2(unlockNumStr, ";")
    local unlockId = string.split2(checkString(unlockIds), ";")
    local length = math.min(#unlockType, #unlockNum)
    local isUnlocked = true
    if length > 0 then
        for i = 1, length do
            local unlockTargetType = checkInt(unlockType[i])
            local unlockTargetNum = checkInt(unlockNum[i])
            local unlockTargetId = checkInt(unlockId[i])
            isUnlocked = GameUtils.IsUnlockedSingle(unlockTargetType, unlockTargetNum, unlockTargetId)
            if not isUnlocked then
                break
            end
        end
    end
    return isUnlocked
end

function GameUtils.IsUnlockedSingle(unlockTargetType, unlockTargetNum, unlockTargetId)
    unlockTargetType = checkInt(unlockTargetType)
    unlockTargetNum = checkInt(unlockTargetNum)
    unlockTargetId = checkInt(unlockTargetId)
    if unlockTargetType > 0 then
        ---判断解锁条件
        if unlockTargetType == Constants.CommonUnlockType.PlayerLevel then
            if GameUtils.GetPlayerLevel() < unlockTargetNum then
                return false
            end
        elseif unlockTargetType == Constants.CommonUnlockType.Gold then
            return false
        elseif unlockTargetType == Constants.CommonUnlockType.Diamond then
            return false
        elseif unlockTargetType == Constants.CommonUnlockType.PassQuest or unlockTargetType == Constants.CommonUnlockType.PassQuest2 then
            local isPass = QuestConfMgr:GetInstance():IsPassQuest(unlockTargetNum)
            if not isPass then
                return false
            end
        elseif checkInt(unlockTargetType) == Constants.CommonUnlockType.PassChallengeQuest then
            local isPass = QuestConfMgr:GetInstance():IsPassQuest(unlockTargetNum)
            if not isPass then
                return false
            end
        elseif unlockTargetType == Constants.CommonUnlockType.PassChapter then
            local isUnLock = QuestConfMgr:GetInstance():IsUnlockChapter(unlockTargetNum)
            if not isUnLock then
                return false
            end
        elseif unlockTargetType == Constants.CommonUnlockType.Likability then
            --好感度
            local dojo = PhoneUtils.GetCatDojoById(unlockTargetId)
            if dojo then
                return checkNumber(dojo.favorabilityLevel) >= checkNumber(unlockTargetNum)
            end
        elseif unlockTargetType == Constants.CommonUnlockType.GetRole then
            --获取到角色
            return PhoneUtils.IsUnlockCatById(unlockTargetId)
        elseif unlockTargetType == Constants.CommonUnlockType.MonthCard then
            ---@type StoreComponent
            local storeComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.StoreComponent)
            return storeComp:IsMonthCardActive(unlockTargetId)
        elseif unlockTargetType == Constants.CommonUnlockType.PTActivity then
            --todo 桂池说的 Constants.CommonUnlockType.PTActivity 对应竹林活动副本 2021.3.30 18:12
            --todo 陈红说 Constants.CommonUnlockType.PTActivity 对应一整类 
            --todo 出问题找以上 
            --todo 竹林 1   
            if unlockTargetId == 1 then
                local BambooUtils = import('Game.UI.FightReady.UIBamboo.BambooUtils')
                return BambooUtils.IsPassMap(unlockTargetNum)
            end
        elseif unlockTargetType == Constants.CommonUnlockType.TeamLevel then
            local cardComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.CardComponent)
            local teamLevel = cardComp:GetRatingId()
            return checkNumber(teamLevel) >= checkNumber(unlockTargetNum)
        elseif unlockTargetType == Constants.CommonUnlockType.CatHouseCatType then
            --猫屋猫种
            --CatHouseMgr:GetInstance():GetCatDataById(id)
            local component = GameUtils.CreateEntityWithComponent(Constants.CatHouseEntityId, ECSComponentType.Constants.CatHouseComponent)
            if component then
                local t = component:GetCatHouseHomeDojo()
                if t then
                    t = t.catList
                    if t then
                        for k, v in pairs(t) do
                            local catStatus = component:GetCDDataById(v.id)
                            --孵化中是false
                            if catStatus and catStatus[4] then

                            else
                                if checkNumber(v.catId) == checkNumber(unlockTargetNum) then
                                    return true
                                end
                            end
                        end
                    end
                end
                return false
            else
                return false
            end
        elseif unlockTargetType == Constants.CommonUnlockType.CatHouseCatGene then
            --猫屋猫基因
            local component = GameUtils.CreateEntityWithComponent(Constants.CatHouseEntityId, ECSComponentType.Constants.CatHouseComponent)
            if component then
                local t = component:GetCatHouseHomeDojo()
                if t then
                    t = t.catList
                    if t then
                        local genesT = checkTable(t.genes)
                        for k, v in pairs(genesT) do
                            if checkNumber(v) == checkNumber(unlockTargetNum) then
                                return true
                            end
                        end
                    end
                end
                return false
            else
                return false
            end
        elseif unlockTargetType == Constants.CommonUnlockType.MaidCoffeeLevel then
            ---@type MaidCoffeePlayerComponent
            local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
            local maidCoffeeLevel = component:GetCafeLevel()
            return checkNumber(maidCoffeeLevel) >= checkNumber(unlockTargetNum)
            -- 咖啡馆星级
        elseif unlockTargetType == Constants.CommonUnlockType.MaidCoffeeStar then
            ---@type MaidCoffeePlayerComponent
            local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
            local maidCoffeeStarLevel = component:GetCafeStarLevel()
            return checkNumber(maidCoffeeStarLevel) >= checkNumber(unlockTargetNum)
            -- 区域好感度
        elseif unlockTargetType == Constants.CommonUnlockType.RegionLikability then
            local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
            local lv, exp = ActionUtils.GetRegionalPointLikabilityLevel(unlockTargetId)
            return checkNumber(lv) >= checkNumber(unlockTargetNum)
        elseif unlockTargetType == Constants.CommonUnlockType.RegionQuest then
            local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
            return ActionUtils.IsPassRegionQuest(unlockTargetNum)
        elseif unlockTargetType == Constants.CommonUnlockType.RegionQuestUnlock then
            local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
            return ActionUtils.IsUnlockRegionQuest(unlockTargetNum)
            -- 主线任务
        elseif unlockTargetType == Constants.CommonUnlockType.MainQuestTask then
            local isPass = QuestConfMgr:GetInstance():IsPassQuest(unlockTargetNum)
            if isPass then
                return true
            end
            local isUnlock = QuestConfMgr:GetInstance():IsUnlockQuest(unlockTargetNum)
            if not isUnlock then
                return false
            end

            local questComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)
            local data = questComponent:GetCurTaskInfo()
            --没任务信息
            if not data then
                return false
            end

            --没有领取任务
            if checkNumber(data.id) <= 0 then
                return false
            end
            -- 社团等级
        elseif unlockTargetType == Constants.CommonUnlockType.ClubLevel then
            local ClubUtils = import('Game.Utils.ClubUtils')
            if ClubUtils.GetClubComp():IsJoinClub() then
                return checkInt(ClubUtils.GetClubComp():GetHomeDojo().level) >= checkNumber(unlockTargetNum)
            else
                return false
            end
            -- 钓鱼解锁
        elseif unlockTargetType == Constants.CommonUnlockType.GetFish then
            local FishingUtils = import('Game.UI.Fishing.FishingUtils')
            local hasNum = FishingUtils.GetFishNumById(unlockTargetId)
            -- return hasNum >= unlockTargetNum
            return hasNum > 0
            -- 获取武装
        elseif unlockTargetType == Constants.CommonUnlockType.QualityCards then
            local quality = unlockTargetId
            local targetNum = unlockTargetNum
            ---@type CardComponent
            local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
            if cardComp then
                local cardDojos = cardComp:GetAllCardTable()
                local cardConf = CardConfMgr:GetInstance()
                local havNum = 0
                for _, cardDojo in ipairs(cardDojos) do
                    ---@type CardVo
                    local cardVo = cardConf:GetCardByRefId(cardDojo.cardId)
                    if cardVo then
                        if checkNumber(cardVo.rare) >= quality then
                            havNum = havNum + 1
                        end
                    end
                end
                return havNum >= targetNum
            end
        elseif unlockTargetType == Constants.CommonUnlockType.GetCard then
            local cardComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.CardComponent)
            return cardComp:IsHasCard(unlockTargetNum)
        elseif unlockTargetType == Constants.CommonUnlockType.PayPoint then
            ---@type PlayerComponent
            local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            ---@type PlayerDojo
            local playerDojo = playerComponent.playerDojo
            return checkNumber(playerDojo.payCumulative) >= checkNumber(unlockTargetNum)
        else
            --不认识的类型直接返回false
            return false
        end
    end
    return true
end

--- 是否打开了系统功能
---@param systemToggleId integer
function GameUtils.IsSwitchedBySystemTogId(systemToggleId)
    ---@type SystemToggleVo
    local vo = CfUtils.SystemToggleVo(systemToggleId) or {}
    return checkInt(vo.switch) > 0
end

---IsUnlockeBySystemTogId
---@param systemToggleId number 功能id
---@param unlockTypes string 解锁类型
---@param unlockNumStr string
function GameUtils.IsUnlockedBySystemTogId(systemToggleId, unlockTypes, unlockNumStr)
    systemToggleId = checkNumber(systemToggleId)
    if systemToggleId == 0 then
        return true
    end

    local vo = CfUtils.SystemToggleVo(systemToggleId)
    if vo then
        --如果是关闭
        if checkNumber(vo.switch) == Constants.ModelFunctionSwitch.Off then
            return false
        end

        if not unlockTypes or not unlockNumStr then
            return GameUtils.IsUnlocked(checkString(vo.unlockType), checkString(vo.unlockNum), checkString(vo.unlockId))
        end
        return (GameUtils.IsUnlocked(checkString(vo.unlockType), checkString(vo.unlockNum), checkString(vo.unlockId)) and GameUtils.IsUnlocked(checkString(unlockTypes), checkString(unlockNumStr), checkString(vo.unlockId)))
    end

    return GameUtils.IsUnlocked(checkString(unlockTypes), checkString(unlockNumStr))
end

---IsUnlockeBySystemTogId 功能id获取解锁描述
---@param systemToggleId number 功能id
function GameUtils.GetUnlockDescrBySystemTogId(systemToggleId)
    systemToggleId = checkNumber(systemToggleId)
    if systemToggleId == 0 then
        return ""
    end

    local vo = CfUtils.SystemToggleVo( systemToggleId)
    if vo then
        return GameUtils.GetUnlockDescr(checkString(vo.unlockType), checkString(vo.unlockNum), checkString(vo.unlockId))
    end

    return ""
end

--- 某个条件 是否解锁
---@param unlockData table
---@return boolean, string
function GameUtils.CheckUnlockedSingle(unlockData)
    if unlockData == nil then
        return true, ""
    end
    local isUnlock = GameUtils.IsUnlockedSingle(unlockData.unlockType, unlockData.unlockNum, unlockData.unlockId)
    if isUnlock then
        return true, ""
    else
        local err = GameUtils.GetUnlockDescr(unlockData.unlockType, unlockData.unlockNum, unlockData.unlockId)
        return false, err
    end
end

--- 使用关卡作为条件，检查功能是否已解锁
---@param questId number 关卡Id
function GameUtils.IsUnlockedByQuestId(questId)
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    if not vo then
        return false, localize("未找到关卡,Id:_num_", { _num_ = questId })
    end
    return GameUtils.CheckUnlockedSingle(vo)
end

