--- 打开网络请求的loading界面
function GameUtils.BeforeRequest()
    local networkLoading = GetLuaBehaviour(CS.UINetLoading.Instance.gameObject, "Game.Main.UINetworkLoading")
    if not isNull(networkLoading) then
        if isNull(networkLoading.Env) then
            networkLoading:Init()
        end
        ---@type UINetworkLoading
        local env = networkLoading.Env
        if env then
            env:BeforeRequest()
        end
    end
    blocker:AddCondition("NETWORK_REQUEST")
end

--- 关闭网络请求的loading界面
function GameUtils.AfterRequest()
    local networkLoading = GetLuaBehaviour(CS.UINetLoading.Instance.gameObject, "Game.Main.UINetworkLoading")
    if not isNull(networkLoading) then
        if isNull(networkLoading.Env) then
            networkLoading:Init()
        end
        ---@type UINetworkLoading
        local env = networkLoading.Env
        if env then
            env:AfterRequest()
        end
    end
    blocker:RemoveCondition("NETWORK_REQUEST")
end

---Request
---开始请求
---@param path string
---@param datas table
---@generic V
---@param onSuccess fun(request:V, response:V):void
---@param onError fun(errStr:V):void
---@param method string @ GET or POST
---@param request Engine.Http.HttpRequest @ 重试请求对象
---@param isShowLoading boolean @ 是否显示加载进度条
---@param isDisableErrorTip boolean @ 是否禁用错误提示
function GameUtils.Request(path, datas, onSuccess, onError, method, request, isShowLoading, isDisableErrorTip)
    if checkInt(IS_REVIEW_INT) > 0 then
        local staticType = typeof(HttpModule)
        local BindingFlags = CS.System.Reflection.BindingFlags
        local propertyInfo = isNotNull(staticType:GetProperty("IsEnableHost", BindingFlags.Static | BindingFlags.Public)) 
        if propertyInfo then
            HttpModule.IsEnableHost = false    
        end
    end
    datas = checkTable(datas)
    datas.ts = tostring(os.time())
    cache[path] = { onSuccess = onSuccess, onError = onError }
    if not isSet(datas, "serializeId1") then
        datas.serializeId1 = tostring(Utils.GenerateId()) ---生成一个id值
    end
    local host = HttpModule.ServerHost
    if Config.DEBUG then
        print(string.format("<color=#3399CC>[HTTP_REQUEST_DATA] %s/%s</color> %s", host, path, table.toString(datas, '')))
    end
    if isNull(isShowLoading) then
        isShowLoading = true
    end
    if not request then
        request = HttpRequest(path, method)
    end
    if isShowLoading then
        if isNull(HttpModule.Instance:HasRequest(request)) then
            blocker:AddCondition(path)
        end
        request.IsNetworkLoading = isShowLoading
        local networkLoading = GetLuaBehaviour(CS.UINetLoading.Instance.gameObject, "Game.Main.UINetworkLoading")
        if not isNull(networkLoading) then
            if isNull(networkLoading.Env) then
                networkLoading:Init()
            end
            ---@type UINetworkLoading
            local env = networkLoading.Env
            if env then
                request.OnBeforeRequest = function()
                    env:BeforeRequest()
                end
                request.OnAfterRequest = function()
                    env:AfterRequest()
                end
            end
        end
    end
    if isNull(method) then
        method = POST
    end
    request.Salt = GameUtils.GetApiSalt()
    request:SetRequestHeader("host", host)
    ---@type UserComponent
    local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
    if isNotNull(userComponent) then
        CfUtils.AddAreaIdRequest(datas)
        ---@type PlayerComponent
        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        if not isNull(playerComponent) then
            local playerId = playerComponent.playerDojo.playerId
            if checkInt(playerId) == 0 then
                ---@type ECSWorldMgr
                local worldMgr = ECSWorldMgr:GetInstance()
                ---@type ECSWorld
                local world = worldMgr:GetWorld(Constants.GameWorld)
                if isNotNull(world) then
                    ---@type ECSEntity
                    local entity = world:GetEntity(Constants.PlayerEntityId)
                    if isNotNull(entity) then
                        local userComp = entity:GetComp(ECSComponentType.Constants.UserComponent)
                        if isNotNull(userComp) then
                            local serverId = 0
                            local cuurentServerId =  checkNumber(userComp.userInfo.cuurentServerId)
                            if cuurentServerId > 0 then
                                serverId = cuurentServerId
                            end
                            if serverId == 0 then
                                local lastServerId = checkNumber(userComp.userInfo.lastLoginServerId)
                                serverId = lastServerId
                            end
                            if serverId > 0 then
                                local serverInfo = userComp:GetServerById(serverId)
                                if isNotNull(serverInfo) then
                                    playerId = tostring(serverInfo.playerId)
                                end
                            end
                        end
                    end
                end
                datas.playerId = tostring(playerId)
            end
            request:SetRequestHeader("User-Agent", string.format('U:%s,P:%s', tostring(userId), tostring(playerId)))
        end
    end
    if method == POST then
        request.RequestDatas = datas
        if Config.DEBUG and not isNull(datas) then
            printLog("HTTP:", table.serialize(datas))
        end
    end
    local operation = HttpModule.StartRequest(
            request,
            function(request, response)
                local responseTable = {}
                if request.Method ~= GET then
                    local jsonStr = response.content
                    if Config.DEBUG then
                        print("HTTP:", jsonStr)
                    end
                    if not string.isEmpty(jsonStr) then
                        responseTable = table.deserialize(jsonStr)
                        if Config.DEBUG then
                            print(string.format("<color=#99CC33>[HTTP_RESPONSE_DATA] %s/%s</color> %s", host, path, table.toString(responseTable, '')))
                        end
                        if checkTable(responseTable) and isSet(responseTable, "errCode") then
                            local code = checkNumber(responseTable.errCode)
                            ---@type Engine.Http.HttpResponse
                            response.code = code
                            response.serverSign = checkString(responseTable.sign)
                            if code ~= 0 then
                                if checkInt(code) == SESSION_ERR_CODE then
                                    ---session过期
                                    GameUtils.SecondConfirm(localize('当前长时间不在游戏中需要退出游戏重新进入'), function()
                                        ---退到登录页面
                                        CS.UnityEngine.Application.Quit()
                                        ---退到登录页面的逻辑暂缓
                                    end, function()
                                        CS.UnityEngine.Application.Quit()
                                    end)
                                else
                                    if isSet(responseTable, "errMsg") and not isDisableErrorTip then
                                        response.errMsg = checkString(responseTable.errMsg)
                                        GameUtils.Toast(response.errMsg .. " T_T ")
                                    end
                                end
                            else
                                if response.mac ~= response.localHashMac then
                                    ---响应的签名验证
                                    GameUtils.SecondConfirm(localize('响应签名验证不正确'), function()
                                        CS.UnityEngine.Application.Quit()
                                    end, function()
                                        CS.UnityEngine.Application.Quit()
                                    end)
                                else
                                    if isSet(responseTable, "data") then
                                        local dataPart = checkTable(responseTable.data)
                                        if isSet(dataPart, "sessionId") then
                                            HttpModule.RequestBodyMeta.SessionId = dataPart.sessionId
                                        end
                                        if isSet(dataPart, "serverTime") then
                                            local serverTime = checkNumber(dataPart.serverTime)
                                            TimeZoneUtils.SetServerTime(serverTime)
                                            response.serverTime = serverTime
                                        end
                                    end
                                end
                            end
                            if Events.HasListener(EVENT_REQUEST_COMPLETE) then
                                Events.Broadcast(EVENT_REQUEST_COMPLETE, code, path)
                            end
                        end
                    end
                end
                ---最终都会响应的
                local successCallback = cache[path].onSuccess
                if not isNull(successCallback) and type(successCallback) == "function" then
                    xpcall(function()
                        successCallback(request, responseTable)
                    end, function(err)
                        printError(string.format("<color=#CC3399>[HTTP_onSuccess_ERROR] %s/%s</color> %s", host, path, err))
                    end)
                    cache[path] = nil
                    blocker:RemoveCondition(path)
                end
            end,
            function(exception)
                blocker:RemoveCondition(path)
                if not isNull(exception) then
                    printError(tostring(exception.Text))
                    ---暂时只处理超时信息弹出重试
                    GameUtils.SecondConfirm(localize('当前网络不稳定，连接失败！'), function()
                        GameUtils.Request(path, datas, onSuccess, onError, method, request, isShowLoading)
                        return true
                    end, function()
                        CS.UnityEngine.Application.Quit()
                    end, localize('(请确认网络环境后重试)'), 3)
                else
                    local errorCallback = cache[path].onError
                    if not isNull(errorCallback) then
                        errorCallback(exception.Text) ---只显示实际的消息
                    else
                        GameUtils.Toast(tostring(exception.Text))
                    end
                end
            end
    )
    return operation
end

