---Toast
---显示一个通用tips提示
---@param text string
---@param okClickAction fun():void
---@param cancelClickAction fun():void
---@param subTitle string @ 子描述
---@param uiType number @ 类别为 1，2 ，3 , 4 普通，网络重试，退出战斗 , 5 商店充值, 6 核心兑换 11 装备预设
---@param consumeVo table @ 消耗类型数据
---@param isQuickClick boolean @ true的时候点击空白处会退出
---@param subTitle2 string @ 提示的内容2
---@param tickCB fun(isConfirmTick:boolean):void
---@param id number @指定的弹窗id
---@param parentTrans UnityEngine.Transform @指定父亲节点
---@param bgForceClose boolean 点击空白处强制关闭，不调用cancel事件
function GameUtils.SecondConfirm(text, okClickAction, cancelClickAction, subTitle, uiType, consumeVo, isQuickClick, subTitle2, tickCB, id, parentTrans, goodTipsType, bgForceClose)
    ---@type Engine.Modules.AbstractResourceLoader
    local loader = ResourceModule.LoadBundleSync("Prefabs/Common/SecondConfirmPopUp.prefab", nil, true)
    if loader.IsSuccess then
        local parent = parentTrans
        if isNull(parentTrans) then
            parent = UIModule.RootCanvas.transform.parent
        end
        --//将检测更新界面加入到初始页面中去
        local go = loader:Instantiate(parent.transform, false)
        loader:Release()

        go.name = "SecondConfirmPopUp"
        if not KTool.IsNull(go) and not KTool.IsNull(parent) then
            local t = go:GetComponent(typeof(RectTransform))
            t.anchorMin = Vector2.zero
            t.anchorMax = Vector2.one
            t.offsetMin = Vector2.zero
            t.offsetMax = Vector2.zero
            t.localPosition = Vector3.zero
            t.localRotation = Quaternion.identity
            t.localScale = Vector3.one
            if parent:IsChildOf(UIModule.RootCanvas.transform) then
                go.layer = parent.gameObject.layer
            end
            -- go.layer = parent.gameObject.layer
            ---获取lua脚本然后执行方法
            local uiSecondConfirm = GetLuaBehaviour(go, "Game.Behaviours.UISecondConfirm")
            if not KTool.IsNull(uiSecondConfirm) then
                ---@type UISecondConfirm
                local uiSecondConfirmEnv = uiSecondConfirm.Env
                uiSecondConfirmEnv:ShowHUD(text, subTitle, okClickAction, cancelClickAction, uiType, checkBool(isQuickClick), consumeVo, subTitle2, tickCB, goodTipsType, bgForceClose)
                if not isNull(id) then
                    uiSecondConfirmEnv:SetTimeTickId(checkNumber(id))
                end
            end
        end
    else
        loader:Release(true)
    end
end

---@param parentTrans UnityEngine.Transform @指定父亲节点
function GameUtils.SecondConfirmClose(parentTrans)
    local parent = parentTrans
    if isNull(parentTrans) then
        parent = UIModule.RootCanvas.transform.parent
    end
    if isNotNull(parent) then
        local go = parent:Find('SecondConfirmPopUp')
        if isNotNull(go) then
            CfUtils.SafeDelete(go.gameObject, true)
        end
    end
end

