---ShowCommonTipsBoard
---显示一个最简单的通用信息提示板 只有标题和描述  *改动*添加id、是否显示两个参数，
---@param targetNode UnityEngine.GameObject 目标
---@param title string 标题
---@param description string 描述
---@param rare number 品质
function GameUtils.ShowCommonTipsBoard(targetNode, title, description, rare, id, isShowNumText, cb, isInTheCenter, uId)
    if checkNumber(id) > 0 then
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(id)
        if vo then
            if checkNumber(vo.effectType) == Constants.GoodsEffectType.ConversionGoodsGroup then
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonChestPreviewPopUpDialog, parameters = { goodsId = id } }, {
                })
                return
            end

            local idType = GoodsUtils.GetIdType(id)
            if idType == Constants.IDType.GoodsCommission then
                GameUtils.ShowCommonTipsEquip(targetNode, id, uId, idType)
                return
            end
        end
    end

    local showNum = isShowNumText ~= false
    if checkNumber(id) == Constants.CoffeeShowItem.PraisePointId then
        showNum = false
    end
    -- 创建prefab
    ResourceModule.LoadGameObjectAsync("Prefabs/Common/CommonTipsBoardBuff.prefab", function(go)
        if not KTool.IsNull(go) and not KTool.IsNull(targetNode) then
            go.name = "CommonTipsBoardBuff"
            local script = GetLuaBehaviour(go, "Game.UI.Common.CommonTipsBoardBuff")
            if not KTool.IsNull(script) then
                -- 刷新提示板内容
                script.Env:RefreshBoardByContent(title, description, rare, id, showNum, nil, uId)
                -- 修正一次坐标位置
                script.Env:FixBoardPosition(targetNode, nil, isInTheCenter)
                -- 界面关闭时的回调
                script.Env:SetCloseCallBack(cb)
            end
        end
    end, true, UIModule.RootCanvas.transform)
end

