---ShowResultTips
---显示结算提示
---@param targetNode UnityEngine.GameObject 目标
---@param goodsId number 道具id
---@param uId number     道具唯一id
function GameUtils.ShowResultTips(targetNode, goodsId, uId, idAreaType, isShowNum)
    local idType = GoodsUtils.GetIdType(goodsId, idAreaType)
    if (uId ~= nil and idType == Constants.IDType.Equipment) or idType == Constants.IDType.GoodsCommission then
        GameUtils.ShowCommonTipsEquip(targetNode, goodsId, uId, idType)
        -- elseif idType == Constants.IDType.GoodsCommission then
        --     local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId, idAreaType)
        --     if vo then
        --         GameUtils.ShowCommonTipsEquip(targetNode, vo.id, uId)
        --     end
    else
        if idType == Constants.IDType.PatrolMazeAssist then
            local PatrolMazeUtils = import('Game.UI.PatrolMaze.PatrolMazeUtils')
            local assistCardVo = PatrolMazeUtils.GetAssistCardVo(goodsId)
            goodsId = assistCardVo.cardId
        end
        ---@type GoodsVo
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId, idAreaType)
        -- print("resultVo====>>" .. table.dump(vo, nil, 3))
        if isTable(vo) then
            GameUtils.ShowCommonTipsBoard(targetNode, vo.name, vo.desc, vo.quality, vo.id, isShowNum, nil, nil, uId)
        end
    end
end

---ShowPlayerInfo
---显示其他玩家的玩家信息
---@param otherPlayerId number     玩家id
---@param exclusiveIds table  互斥界面
function GameUtils.ShowPlayerInfo(otherPlayerId, exclusiveIds, callback, exParameter)
    if isNull(otherPlayerId) then
        return
    end
    GameUtils.Request(
            Interfaces.PlayerViewOthersInfo,
            { otherPlayerId = checkInt(otherPlayerId) },
            function(request, response)
                if checkInt(response.errCode) == 0 then
                    --printInfo("data--------->>"..table.dump(response.data))
                    if response.data.revealTeam == nil or next(response.data.revealTeam) == nil then
                        local refId = CfUtils.GetCfVo(AutoIds.IdSetting950, "PersonalInfoVo", Constants.PersonalInfoVoId.CardDrawingId).num
                        response.data.revealTeam = { CardUtils.GenerateCustomById(refId) }
                    end
                    local data = {
                        playerId = response.data.playerId, --UID
                        playerCreateTime = response.data.playerCreateTime, --入职时间
                        playerName = response.data.name, --玩家角色名
                        playerCardsNum = response.data.playerCardsNum, --玩家卡牌数量
                        playerAvatar = (response.data.avatar or response.data.avatarId), --玩家头像
                        playerAvatarFrame = (response.data.avatarFrame or response.data.avatarFrameId), --玩家头像框
                        level = response.data.level, --玩家等级
                        birthday = response.data.birthday, --个人信息生日
                        revealCard = response.data.revealCard, --个人信息首页卡牌Id
                        revealTeam = response.data.revealTeam, --列表卡牌的服务器Id
                        isFriend = response.data.isFriend == 1, --1 是好友 0 不是
                        ratingId = response.data.ratingId, --小队评级
                        partyCatInfo = checkTable(response.data.partyCatInfo), -- 伙伴猫信息
                        medal = response.data.medal, -- 徽章旧数据
                        medals = response.data.medals, -- 徽章新数据
                        playerThemeId = checkInt(response.data.panel) > 0 and response.data.panel or CfUtils.GetCfVo(AutoIds.IdSetting950, "PersonalInfoVo", Constants.PersonalInfoVoId.DefaultThemeId).num,
                        newQuestId = response.data.newQuestId, -- 主线关卡ID
                        cafeLevel = response.data.cafeLevel, -- 餐厅等级
                        clubId = response.data.clubId, -- 社团ID
                        clubName = response.data.clubName, -- 社团名称
                        overseaClimbingTowerId = response.data.overseaClimbingTowerId, -- 爬塔通关ID
                    }
                    local curCatGenes = {}
                    for _, geneDt in ipairs(checkTable(data.partyCatInfo.genes)) do
                        table.insert(curCatGenes, checkInt(geneDt.geneId))
                    end
                    data.partyCatInfo.genes = curCatGenes

                    local parameter = {
                        openType = 2,
                        data = data,
                        exParameter = exParameter,
                    }
                    if callback == nil then
                        print("koko -- 个人信息界面 入口 -2-")
                        UIModule.OpenDialog(
                                {
                                    --id = Constants.UITypeIds.PlayerNewMainDialog,
                                    id = Constants.UITypeIds.Player2DMainDialog,
                                    parameters = parameter,
                                },
                                exclusiveIds
                        )
                    else
                        callback(parameter)
                    end
                end
            end
    )
end

---OpenLoadingPanel
---loading界面切换
---@param arg Engine.UI.UIArgument
---@param dialogArguments table
---@param loadingType number
---@param isFirst number 是否是第一次进入
function GameUtils.OpenLoadingPanel(arg, dialogArguments, loadingType, isFirst, isSwitchEnterScene)
    local go = UIModule.RootCanvas.transform:Find("ActionTeamInviteNode")
    if not isNull(go) then
        KTool.SafeDelete(go.gameObject)
    end

    if isNull(loadingType) then
        loadingType = Constants.LoadingType.Battle
    end
    if arg and isNull(arg.hasExcluded) then
        arg.hasExcluded = false
    end
    KCookie.Set("isFirst", checkBool(isFirst))
    --if arg and arg.id == Constants.UITypeIds.UISceneHome and loadingType ~= Constants.LoadingType.PVPArena and loadingType ~= Constants.LoadingType.QuestRepeat then
    --    dialogArguments = {}
    --end
    if (arg and (not (loadingType == Constants.LoadingType.SpecifyScene or loadingType == Constants.LoadingType.HomeScene or isSwitchEnterScene))) then
        if UIModule.CurrentScreen then
            UIModule.CurrentScreen.Argument = clone(checkTable(arg))
        end

    end
    if loadingType == Constants.LoadingType.MainHome and checkBool(isFirst) == true then
        ---每一次进入主界面
        blocker:AddCondition("LOADING_PAN")
        xTry(function()

            local parent = UIModule.RootCanvas.gameObject
            local go = GameUtils.LoadBundleSyncById(Constants.UIModulePrefabsIds.LoginLoadingPanel, parent, false, false)
            GameUtils.InitNodeDefaultParams(go, parent)
            if not KTool.IsNull(go) and not KTool.IsNull(parent) then
                go.name = "LoginLoadingPanel"
                ---@type Engine.Modules.LuaBehaviour
                local mono = GetLuaBehaviour(go, "Game.Behaviours.LoginLoadingPanel")
                if not KTool.IsNull(mono) then
                    ---@type LoginLoadingPanel
                    local env = mono.Env
                    env:SetArg(arg, dialogArguments, loadingType, true)
                end

            end
            blocker:RemoveCondition("LOADING_PAN")
        end, function()
            blocker:RemoveCondition("LOADING_PAN")
        end)
    elseif loadingType == Constants.LoadingType.HomeScene then
        local parent = UIModule.RootCanvas.gameObject
        local go = GameUtils.LoadBundleSyncById(Constants.UIModulePrefabsIds.HomeSceneLoadingPanel, parent, false, false)
        GameUtils.InitNodeDefaultParams(go, parent)
        if not KTool.IsNull(go) and not KTool.IsNull(parent) then
            go.name = "HomeSceneLoadingPanel"
            ---@type Engine.Modules.LuaBehaviour
            local mono = GetLuaBehaviour(go, "Game.Behaviours.HomeSceneLoadingPanel")
            if not KTool.IsNull(mono) then
                ---@type HomeSceneLoadingPanel
                local env = mono.Env
                env:SetArg(arg, dialogArguments, loadingType, true)
            end
        end

    elseif loadingType == Constants.LoadingType.PVPFriend then
        local parent = UIModule.RootCanvas.gameObject
        local go = GameUtils.LoadBundleSyncById(Constants.UIModulePrefabsIds.FriendReadyDialog, parent, false, false)
        GameUtils.InitNodeDefaultParams(go, parent)
        if not KTool.IsNull(go) and not KTool.IsNull(parent) then
            go.name = "FriendReadyDialog"
            ---@type Engine.Modules.LuaBehaviour
            local mono = GetLuaBehaviour(go, "Game.Behaviours.UIFriendPVPLoadingPanel")
            if not KTool.IsNull(mono) then
                ---@type UIFriendPVPLoadingPanel
                local env = mono.Env
                env:SetArg(arg, dialogArguments, loadingType, true)
            end
        end
    elseif loadingType == Constants.LoadingType.PVPArena then
        local parent = UIModule.RootCanvas.gameObject
        local go = GameUtils.LoadBundleSyncById(Constants.UIModulePrefabsIds.PVPPlayerReadyDialog, parent, false, false)
        GameUtils.InitNodeDefaultParams(go, parent)
        if not KTool.IsNull(go) and not KTool.IsNull(parent) then
            go.name = "PVPArenaPlayerReadyDialog"
            ---@type Engine.Modules.LuaBehaviour
            local mono = GetLuaBehaviour(go, "Game.UI.PVPArena.PVPArenaPlayerReadyDialog")
            if not KTool.IsNull(mono) then
                ---@type PVPArenaPlayerReadyDialog
                local env = mono.Env
                env:SetArg(arg, dialogArguments, loadingType)
            end
        end
    elseif loadingType == Constants.LoadingType.LadderCompetion then
        local parent = UIModule.RootCanvas.gameObject
        local go = GameUtils.LoadBundleSyncById(Constants.UIModulePrefabsIds.LadderCompetionLoadingDialog, parent, false, false)
        GameUtils.InitNodeDefaultParams(go, parent)
        if not KTool.IsNull(go) and not KTool.IsNull(parent) then
            go.name = "LadderCompetionLoadingDialog"
            ---@type Engine.Modules.LuaBehaviour
            local mono = GetLuaBehaviour(go, "Game.Behaviours.LadderCompetionLoadingDialog")
            if not KTool.IsNull(mono) then
                ---@type LadderCompetionLoadingDialog
                local env = mono.Env
                env:SetArg(arg, dialogArguments, loadingType, true)
            end
        end
    elseif loadingType == Constants.LoadingType.SpecifyScene then
        local parent = UIModule.RootCanvas.gameObject
        local go = GameUtils.LoadBundleSyncById(Constants.UIModulePrefabsIds.SpecifySceneLoadingPanel, parent, false, false)
        GameUtils.InitNodeDefaultParams(go, parent)
        if not KTool.IsNull(go) and not KTool.IsNull(parent) then
            go.name = "SpecifySceneLoadingPanel"
            ---@type SpecifySceneLoadingPanel
            local env = CfUtils.GetLuaScr(go, "Game.Behaviours.SpecifySceneLoadingPanel")
            if not isNull(env) then
                env:SetArg(arg, dialogArguments, loadingType, true)
            end
        end

    else
        if loadingType == Constants.LoadingType.MainHome then
            ---战斗退出时的逻辑
            ---退出战斗的情况
            ---关闭所有的窗口
            blocker:AddCondition("BACK_MAIN_HOME")
            local args = FightPreWarMgr:GetInstance():GetBattleArgs()
            local isDisableRecoveryBgm = isNotNull(args) and args.isDisableRecoveryBgm or false
            FightPreWarMgr:GetInstance():ClearBattleBuff()
            GameUtils.HideBlack(0.3)    -- 战斗结束以后，如果是因为不可抗力退出，就不会经过结算界面，可能会有关尾剧情的黑屏没有关闭，这里关一下
            GameUtils.ShowBlackOverlay(nil, function()
                if BattleViewMgr then
                    BattleViewMgr:SetCameraVMActive(false)
                    BattleViewMgr:ResetOutsetBattleSettings()
                end
                if BattleEndMgr then
                    --- 结算表演的timeline会改镜头焦距，需要在打开主场景之前先重置掉才行
                    BattleEndMgr:ResetCameraAndLight()
                    -- 50皮结算会deactive阴影，退出战斗要active一下
                    BattleEndMgr:SetActiveLowDiscShadow(true)
                end

                -- 退出组队聊天
                local social = AppService:GetInstance():GetSocialLine()
                if social then
                    social:ExitTeamRoom()
                    social:ExitVoiceRoom()
                end

                local coWait = CoWait.Start()
                local count = UIModule.CurrentScreen.dialogs.Count
                xTry(function()
                    for i, v in support.list_ipairs(UIModule.CurrentScreen.dialogs) do
                        if not isNull(v) then
                            local co = UIModule.CloseDialog(v, true)
                            if not isNull(co) then
                                coWait:Coroutine(co)
                            end
                        end
                    end
                    UIModule.CurrentScreen.dialogs:Clear()
                end)
                while not coWait.IsFinish and count > 0 do
                    coroutine.yield()
                end

                Events.Broadcast(Constants.EventNames.FightEndPreHandle)
                xpcall(function()
                    UINavigationBarRoot.Instance:SetActive(true)
                    if BattleViewMgr then
                        BattleViewMgr:OnDestroy()
                        BattleViewMgr = nil
                    end
                    CS.UnityEngine.LightmapSettings.lightProbes = nil
                end, function(err)
                    local nativeFXMgr = CS.Game.Native.ParticleManager.Instance
                    nativeFXMgr:TearDown()
                    printError(tostring(err))
                end)
                cs_coroutine.yield_return()

                local cb = FightPreWarMgr:GetInstance():GetFightEndPreHandle()
                if cb then
                    cb()
                end
                local arguments = UIModule.PopPage()
                if not isNull(arguments) and arguments.Count > 0 then
                    xpcall(function()
                        for i, v in support.list_ipairs(arguments) do
                            cs_coroutine.yield_return(UIModule.OpenDialog(v.id, v))
                        end
                    end, function()
                        printError("[OpenLoadingPanel] OpenDialog Error")
                        cs_coroutine.yield_return(UIModule.OpenDialog({ id = Constants.UITypeIds.UIHomeView }))
                    end)
                else
                    ---初始需要打包主界面
                    cs_coroutine.yield_return(UIModule.OpenDialog({ id = Constants.UITypeIds.UIHomeView }))
                end

                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.6))

                -- 退出战斗切换BGM
                local backToMainChapterPanel = false
                if isNotNull(arguments) and arguments.Count > 0 then
                    xpcall(function()
                        for i, v in support.list_ipairs(arguments) do
                            if v.id == Constants.UITypeIds.UIMainBattlePanelDialog
                                    or v.id == Constants.UITypeIds.UIMainChapterDialog then
                                backToMainChapterPanel = true
                            end
                        end
                    end, function()
                        printError("[OpenLoadingPanel] OpenDialog Error 1")
                    end)
                end
                if not isDisableRecoveryBgm then
                    if backToMainChapterPanel then
                        local bgmId = QuestConfMgr:GetInstance():GetCurrentMainChapterBGM()
                        if not string.isEmpty(bgmId) then
                            CriWareUtils.PlayMusicById(bgmId)
                        else
                            CriWareUtils.PlayRandomBGMFromCDList()
                        end
                    else
                        local id = KCookie.Get("RecoveryBGMID")
                        if isNotNull(id) then
                            CriWareUtils.PlayMusicById(id)
                        else
                            CriWareUtils.PlayRandomBGMFromCDList()
                        end
                    end

                end
                blocker:RemoveCondition("BACK_MAIN_HOME")
                if loadingType == Constants.LoadingType.MainHome then
                    ---如果是去主界面的
                    Events.Broadcast(Constants.EventNames.ScreenBackEvent)
                end
            end, function()
                -- 猫头消失以后
                Events.Broadcast(Constants.EventNames.ExitBattleLoadOver)
            end)
        else
            ---进入战斗的逻辑
            local parent = UIModule.RootCanvas.gameObject
            local go = GameUtils.LoadBundleSyncById(Constants.UIModulePrefabsIds.LoadingPanel, parent, false, false)
            GameUtils.InitNodeDefaultParams(go, parent)
            if not KTool.IsNull(go) and not KTool.IsNull(parent) then
                go.name = "LoadingPanel"
                ---@type Engine.Modules.LuaBehaviour
                local mono = GetLuaBehaviour(go, "Game.Behaviours.UILoadingPanel")
                if not KTool.IsNull(mono) then
                    ---@type UILoadingPanel
                    local env = mono.Env
                    env:SetArg(arg, dialogArguments, loadingType, true)
                end
            end
        end
    end
end

--战斗退出至其他界面
function GameUtils.BattleToOtherDialog(id, args)
    ---战斗退出时的逻辑
    ---退出战斗的情况
    ---关闭所有的窗口
    FightPreWarMgr:GetInstance():ClearBattleBuff()
    cs_coroutine.start(function()
        if BattleViewMgr then
            BattleViewMgr:SetCameraVMActive(false)
            BattleViewMgr:ResetOutsetBattleSettings()
        end
        if BattleEndMgr then
            --- 结算表演的timeline会改镜头焦距，需要在打开主场景之前先重置掉才行
            BattleEndMgr:ResetCameraAndLight()
        end

        local coWait = CoWait.Start()
        local count = UIModule.CurrentScreen.dialogs.Count
        xTry(function()
            for i, v in support.list_ipairs(UIModule.CurrentScreen.dialogs) do
                if not isNull(v) then
                    if checkNumber(v.Argument.id) > 599 and checkNumber(v.Argument.id) < 700 then
                        local co = UIModule.CloseDialog(v, true)
                        if not isNull(co) then
                            coWait:Coroutine(co)
                        end
                    end
                end
            end
        end)
        while not coWait.IsFinish and count > 0 do
            coroutine.yield()
        end

        Events.Broadcast(Constants.EventNames.FightEndPreHandle)
        cs_coroutine.yield_return(UIModule.OpenDialog({ id = id, parameters = { args = args } }))

        xpcall(function()

            if BattleViewMgr then
                BattleViewMgr:OnDestroy()
                BattleViewMgr = nil
            end
            CS.UnityEngine.LightmapSettings.lightProbes = nil
        end, function(err)
            local nativeFXMgr = CS.Game.Native.ParticleManager.Instance
            nativeFXMgr:TearDown()
            printError(tostring(err))
        end)

        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.6))
        CriWareUtils.PlayRandomBGMFromCDList()
    end)
end

function GameUtils.InitNodeDefaultParams(gameObject, parent)
    if isNull(gameObject) then
        return
    end
    local t = gameObject:GetComponent(typeof(RectTransform))
    t.anchorMin = Vector2.zero
    t.anchorMax = Vector2.one
    t.offsetMin = Vector2.zero
    t.offsetMax = Vector2.zero
    t.localPosition = Vector3.zero
    t.localRotation = Quaternion.identity
    t.localScale = Vector3.one
    if not isNull(parent) then
        gameObject.layer = parent.gameObject.layer
    end
end

---BackToGameStart
---返回到主界面登录页面
function GameUtils.BackToGameStart()
    blocker:AddCondition("BackToGameStart")
    ShowOverlay()
    CS.Engine.Lib.CoWait.Start():Coroutine(util.cs_generator(function()
        if SettingVoiceMgr then
            SettingVoiceMgr:Clear()
            SettingVoiceMgr = nil
            unimport("Game.UI.Setting.SettingVoiceMgr")
        end
        if BattleViewMgr then
            -- 如果在战斗中，退出战斗
            GameUtils.ExitBattle()
        end
        if GameUtils.IsInAnnihilation() then
            -- 如果在歼灭战组队房间，清理房间
            local RegionQuestMgr = import('Game.UI.FightReady.UIMainChapter.RegionQuestMgr')
            CoYield(RegionQuestMgr:GetInstance():Clear())
        end
        ---测试返回登录界面的逻辑
        KCookie.Set(Constants.UICacheDataKeys.OVERSEA_MANAGER_SCENE_STATE, 0)
        xTry(function()
            local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
            CriWareUtils.StopLastBGMMusic()
            ---@type UnityEngine.Transform
            local loadingTrans = KTool.DFSFindObject(UIModule.RootCanvas.transform, "UILoadingPanel")
            if not isNull(loadingTrans) then
                ---如果是在加载过程中不能回到登录界面
                return
            end
            ---半闭长连接
            CS.Engine.Network.KNManager.canRetry = false
            local UINetLoadingInstance = CS.UINetLoading.Instance
            if UINetLoadingInstance then
                CfUtils.SetActive(UINetLoadingInstance.gameObject, false)
            end
            if AppService then
                -- 需要发出 Constants.EventNames.ONAPPQUIT 事件
                AppService:GetInstance():OnAppQuitHandler()
                AppService:GetInstance():Delete()
            end
            ---@type AppService
            AppService = nil
            ---@type GuideComponent
            local guideComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.GuideComponent)
            if guideComponent then
                guideComponent:DestroyGuide()
            end
            GameUtils.CloseWaterMark()
            xTry(function()
                local child = UIModule.RootCanvas.transform.childCount
                for i = 1, child do
                    local childNode = UIModule.RootCanvas.transform:GetChild(i - 1)
                    if not isNull(childNode) and not isNull(childNode.gameObject) then
                        if string.contains(childNode.name, "CommonTipsPanel") then
                            KTool.SafeDelete(childNode.gameObject)
                        end
                    end
                end
            end)

            CS.Engine.Modules.CDTimerModule.GetInstance():Clear()
            CS.Engine.Modules.TimerModule.Instance:Stop()
            ---清除所有的倒计时
            CS.Engine.Lib.KCookie.PurgeCache()
            ---清理pool manger中的缓存
            local PoolManager = CS.Engine.Lib.PoolManager
            PoolManager.Instance:TearDownAll()
            ---清理配表
            CS.UINavigationBarRoot.Instance:SetActive(false)
            ---清lua缓存
            cs_coroutine.yield_return(Yielders.EndOfFrame)
            UIModule.ResetStack()
            local coWait = CoWait.Start()
            local count = UIModule.CurrentScreen.dialogs.Count
            xTry(function()
                for i, v in support.list_ipairs(UIModule.CurrentScreen.dialogs) do
                    if not isNull(v) then
                        local co = UIModule.CloseDialog(v, true)
                        if not isNull(co) then
                            coWait:Coroutine(co)
                        end
                    end
                end
                UIModule.CurrentScreen.dialogs:Clear()
            end)
            while not coWait.IsFinish and count > 0 do
                coroutine.yield()
            end
            ---清理缓存
            cs_coroutine.yield_return(UIModule.Clear())
            ---重置ui界面记录
            cs_coroutine.yield_return(UIModule.Hide(UIModule.CurrentScreen))
            ---重置ui界面记录
            UIModule.ScreenHistory:Clear()
            local rootTrans = KTool.DFSFindObject(UIModule.RootCanvas.transform, "GameRoot")
            if not isNull(rootTrans) then
                KTool.SetActive(rootTrans.gameObject, true)
                UIModule.CurrentScreen = rootTrans:GetComponent(typeof(CS.Game.Native.GameEntry))
            end
            ---清理缓存
            --UIModule.Clear()
            RestartVmReload(function()
                -- 退出登陆重置一下登陆的状态
                local SDKService = import('Game.Entry.SDKService')
                -- 游戏退出 表示已经登录过一次
                SDKService:GetInstance():SetIsLogin(false)
                KCookie.Set("GAME_BACK_TO_LOGIN", 1)
                ---刷新一次版本号信息
                CS.Game.Native.Game.Instance:LoadVersion(true)
                Events.Broadcast("OnBackToGameStartBefore")
                cs_coroutine.yield_return(UIModule.OpenDialog({ id = Constants.UITypeIds.LoginDialog }))
                Events.Broadcast("OnBeforeStart")
                blocker:RemoveCondition("BackToGameStart")
                Events.Broadcast("OnBackToGameStartAfter")
            end)
        end, function()
            printError(debug.traceback())
            blocker:RemoveCondition("BackToGameStart")
        end)
    end))
end

function GameUtils.ExitBattle()
    if FightPreWarMgr then
        FightPreWarMgr:GetInstance():ClearBattleBuff()
    end
    GameUtils.HideBlack(0.3)    -- 战斗结束以后，如果是因为不可抗力退出，就不会经过结算界面，可能会有关尾剧情的黑屏没有关闭，这里关一下
    if BattleViewMgr then
        BattleViewMgr:SetCameraVMActive(false)
        BattleViewMgr:ResetOutsetBattleSettings()
    end
    if BattleEndMgr then
        --- 结算表演的timeline会改镜头焦距，需要在打开主场景之前先重置掉才行
        BattleEndMgr:ResetCameraAndLight()
    end

    -- 退出组队聊天
    local social = AppService:GetInstance():GetSocialLine()
    if social then
        social:ExitTeamRoom()
        social:ExitVoiceRoom()
    end

    xpcall(function()
        if UINavigationBarRoot then
            UINavigationBarRoot.Instance:SetActive(true)
        end
        if BattleViewMgr then
            BattleViewMgr:OnDestroy()
            BattleViewMgr = nil
        end
        CS.UnityEngine.LightmapSettings.lightProbes = nil
    end, function(err)
        local nativeFXMgr = CS.Game.Native.ParticleManager.Instance
        if nativeFXMgr then
            nativeFXMgr:TearDown()
        end
        printError(tostring(err))
    end)
end

