---GetEntity
---获得实体
---@param entityId integer | nil
---@return ECSEntity
function GameUtils.GetEntity(entityId)
    ---@type ECSWorldMgr
    local worldMgr = ECSWorldMgr:GetInstance()
    ---@type ECSWorld
    local world = worldMgr:GetWorld(Constants.GameWorld)
    if isNull(world) then
        return
    end
    if isNull(entityId) then
        entityId = Constants.PlayerEntityId
    end
    ---@type ECSEntity
    return world:GetEntity(entityId)
end

function GameUtils.CreateEntityWithComponent(entityId, component)
    ---@type ECSWorldMgr
    local worldMgr = ECSWorldMgr:GetInstance()
    ---@type ECSWorld
    local world = worldMgr:GetWorld(Constants.GameWorld)
    ---@type ECSEntity
    local entity = nil
    if not world:HasEntity(entityId) then
        entity = world:CreateEntity(entityId, entityId)
    else
        entity = world:GetEntity(entityId)
    end
    return entity:GetOrAddComp(component)
end

