---LoadBundleSync
---@param path string bundle path
---@param parent UnityEngine.GameObject
---@param worldPositionStays boolean
---@param isWaitCompleted boolean
---@return UnityEngine.GameObject, Engine.Modules.AbstractResourceLoader
function GameUtils.LoadBundleSync(path, parent, worldPositionStays, isWaitCompleted)
    --parent不为空，表示有父节点
    local hasParent = not KTool.IsNull(parent)

    local loader
    if isWaitCompleted then
        loader = ResourceModule.LoadBundleAsync(path, nil, true)
        while not loader.IsCompleted do
            cs_coroutine.yield_return(Yielders.EndOfFrame)
        end
    else
        loader = ResourceModule.LoadBundleSync(path, nil, true)
    end

    local go
    if loader.IsSuccess then
        ---如果加载时parent存在，但是加载完成之后，parent已经被销毁，则当前对象也要销毁
        if (hasParent and not KTool.IsNull(parent)) or not hasParent then

            go = loader:Instantiate()
            if not KTool.IsNull(go) then
                go.name = string.stripExtension(string.stripFileName(path))

                if not KTool.IsNull(parent) then
                    KTool.SetParent(go, parent.gameObject, checkBool(worldPositionStays))
                end
            end
        end

    end
    loader:Release()
    -- loader = nil
    --loader:Release()
    return go
end

---@param id Constants.UIModulePrefabsIds
---@param parent UnityEngine.GameObject
---@param isWorldPos boolean
---@return UnityEngine.GameObject
function GameUtils.LoadBundleAsyncById(id, parent, isWorldPos)
    local path = GameUtils.GetUIModulePrefabsPath(id)
    local go = GameUtils.LoadBundleAsync(path, parent, isWorldPos)
    return go
end

---@param path string
---@param parent UnityEngine.GameObject
---@param isWorldPos boolean
---@return UnityEngine.GameObject
function GameUtils.LoadBundleAsync(path, parent, isWorldPos)
    --parent不为空，表示有父节点
    local hasParent = not KTool.IsNull(parent)

    -- 编辑器下 并且 非ab加载的模式
    if Application.isEditor and ResourceModule.IsEditorLoadAsset then
        -- 制造短暂的延迟，模拟ab模式下异步加载产生的时间错位
        -- 可用于及时发现有些完成回调并没有等待加载完成的疏漏
        CoYield()
    end

    local loader = ResourceModule.LoadBundleAsync(path, nil, true)
    while not loader.IsCompleted do
        cs_coroutine.yield_return(Yielders.EndOfFrame)
    end

    local go
    if loader.IsSuccess then
        ---如果加载时parent存在，但是加载完成之后，parent已经被销毁，则当前对象也要销毁
        if (hasParent and not KTool.IsNull(parent)) or not hasParent then
            go = loader:Instantiate()
            if not KTool.IsNull(go) then
                go.name = string.stripExtension(string.stripFileName(path))

                if not KTool.IsNull(parent) then
                    KTool.SetParent(go, parent.gameObject, checkBool(isWorldPos))
                end
            end
        end
    end
    loader:Release()

    return go
end

