local BlackOverlayPath = "Game.Behaviours.BlackOverlayMB"
---ShowBlackOverlay
---显示黑屏层的过渡的逻辑
---@param cb fun():void
---@param waitCort fun():void
---@param endCallback fun():void | nil
---@return number, number, UnityEngine.Transform @ entryTime, endTime
function GameUtils.ShowBlackOverlay(cb, waitCort, endCallback, customPrefab)
    local uiRootTrans = UIModule.RootCanvas.transform.parent.transform

    local goName = "UIBlackOverlay"
    local uiBlackOverlayGo = uiRootTrans:Find(goName)
    if not uiBlackOverlayGo then
        local prefabPath
        if customPrefab then
            prefabPath = customPrefab
        else
            prefabPath = "Prefabs/Common/CommonTransition.prefab"
        end
        local loader = CS.Engine.Modules.ResourceModule.LoadBundleSync(prefabPath, nil, true)
        if not loader.IsSuccess then
            loader:Release(true)
        end
        uiBlackOverlayGo = loader:Instantiate()
        loader:Release()

        KTool.SetParent(uiBlackOverlayGo, uiRootTrans.gameObject, false)
        ---@type UnityEngine.RectTransform
        local rect = KTool.GetComponent(uiBlackOverlayGo, typeof(CS.UnityEngine.RectTransform))
        rect.sizeDelta:Set(0, 0)
        rect.offsetMin = Vector2.New(0, 0)
        rect.offsetMax = Vector2.New(0, 0)
        rect.anchorMin = Vector2.New(0, 0)
        rect.anchorMax = Vector2.New(1, 1)
        uiBlackOverlayGo.name = goName
        local blackOverlayMB = AddLuaBehaviour(uiBlackOverlayGo.gameObject, BlackOverlayPath)

        if isNull(blackOverlayMB.Env) then
            blackOverlayMB:Init()
        end
        -- if not isNull(blackOverlayMB.Env) then
        --     blackOverlayMB.Env.loader = loader
        -- else
        --     loader:Release(true)
        -- end
    end

    local entryTime, endTime = 0, 0
    if uiBlackOverlayGo then
        local blackOverlayMB = AddLuaBehaviour(uiBlackOverlayGo.gameObject, BlackOverlayPath)
        if isNull(blackOverlayMB.Env) then
            blackOverlayMB:Init()
        end
        if not isNull(blackOverlayMB.Env) then
            ---@type BlackOverlayMB
            local env = blackOverlayMB.Env
            env:SetFadeInCb(cb)
            env:SetWaitCort(waitCort)
            env:SetEndCb(endCallback)
            entryTime, endTime = env:StartAnimation()
        end
    end
    return entryTime, endTime, uiBlackOverlayGo
end

--- 遮黑
---@param inDuration number 淡入时长
---@param duration number 全黑时长
---@param outDuration number 淡出时长
---@param targetColor Color 黑色
function GameUtils.ShowBlackDuration(inDuration, duration, outDuration, targetColor)
    local navigatorEnv = CfUtils.GetLuaScr(CS.UINavigationBarRoot.Instance.gameObject, "Game.Main.UINavigatorBar")
    local blackGo = navigatorEnv.backAnimationGo
    if isNull(blackGo) then
        return
    end
    if navigatorEnv.isStart then
        return
    end

    -- print("[黑幕] duration start", debug.traceback())
    targetColor = targetColor or Color.black
    return cs_coroutine.start(function()
        navigatorEnv.isStart = true
        KTool.SetActive(blackGo, true)

        -- 我们不用animation，关掉它
        local animation = KTool.GetComponent(blackGo, typeof(CS.UnityEngine.Animation))
        if not isNull(animation) then
            animation.enabled = false
        end

        -- 淡入
        local TF_Img = blackGo.transform:GetChild(0)
        local img = TF_Img:GetComponent(typeof(CS.UnityEngine.UI.Image))
        local color = DeepCopy(targetColor)
        color.a = 0
        img.color = color
        if inDuration > 0 then
            img:DOFade(1, inDuration)
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(inDuration))
        end
        img.color = targetColor

        -- 遮黑
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(duration))

        -- 淡出
        local TF_Img = blackGo.transform:GetChild(0)
        local img = TF_Img:GetComponent(typeof(CS.UnityEngine.UI.Image))
        img.color = targetColor
        if outDuration > 0 then
            img:DOFade(0, outDuration)
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(outDuration))
        end
        img.color = Color.black

        KTool.SetActive(blackGo, false)

        -- 把人家的animation打开，还原回去
        if not isNull(animation) then
            animation.enabled = true
        end
        navigatorEnv.isStart = false
        -- print("[黑幕] duration end")
    end)
end

--- 显示黑屏（这个黑屏不会自己关闭，需要在合适的时机，自己调用HideBlack）
---@param inDuration number
---@param targetColor Color
function GameUtils.ShowBlack(inDuration, targetColor, onShowEnd)
    local navigatorEnv = CfUtils.GetLuaScr(CS.UINavigationBarRoot.Instance.gameObject, "Game.Main.UINavigatorBar")
    local blackGo = navigatorEnv.backAnimationGo

    if isNull(blackGo)
            or navigatorEnv.isStart then
        if onShowEnd then
            onShowEnd()
        end
        return
    end

    -- print("[黑幕] show start", inDuration, debug.traceback())
    targetColor = targetColor or Color.black
    KTool.SetActive(blackGo, true)

    -- 我们不用animation，关掉它
    local animation = KTool.GetComponent(blackGo, typeof(CS.UnityEngine.Animation))
    if not isNull(animation) then
        animation.enabled = false
    end

    local TF_Img = blackGo.transform:GetChild(0)
    local img = TF_Img:GetComponent(typeof(CS.UnityEngine.UI.Image))
    local color = DeepCopy(targetColor)
    color.a = 0
    img.color = color
    navigatorEnv.showBlackTween = img:DOFade(1, inDuration):OnComplete(function()
        if onShowEnd then
            onShowEnd()
        end
        navigatorEnv.showBlackTween = nil
        -- print("[黑幕] show end", inDuration)
    end)
end

--- 隐藏黑屏
---@param outDuration number
function GameUtils.HideBlack(outDuration)
    local navigatorEnv = CfUtils.GetLuaScr(CS.UINavigationBarRoot.Instance.gameObject, "Game.Main.UINavigatorBar")
    local blackGo = navigatorEnv.backAnimationGo

    if isNull(blackGo) then
        return
    end

    if blackGo.activeSelf == false then
        return
    end

    -- print("[黑幕] hide start", outDuration, debug.traceback())
    navigatorEnv.hideBlackCo = cs_coroutine.start(function()
        if isNotNull(navigatorEnv.showBlackTween) then
            cs_coroutine.yield_return(navigatorEnv.showBlackTween)
        end

        local TF_Img = blackGo.transform:GetChild(0)
        local img = TF_Img:GetComponent(typeof(CS.UnityEngine.UI.Image))
        img:DOFade(0, outDuration):OnComplete(function()
            KTool.SetActive(blackGo, false)

            -- 把人家的animation打开，还原回去
            local animation = KTool.GetComponent(blackGo, typeof(CS.UnityEngine.Animation))
            if not isNull(animation) then
                animation.enabled = true
            end
            navigatorEnv.hideBlackCo = nil
            -- print("[黑幕] hide end", outDuration)
        end)
    end)
end

---BindRedPoint
---设置节点小红点回调
---@param strNode Constants.RedPointConst @ 红点节点定义
---@param redParGo UnityEngine.GameObject 小红点的父节点
---@param isInvoke boolean @ 是否立即激活一次回调
---@param anchoredPos UnityEngine.Vector2 | nil
---@param cb fun(node:RedPointDojo):void | nil @ 自定义回调
---@param type any 小红点类型  不同的图片
function GameUtils.BindRedPoint(strNode, redParGo, isInvoke, anchoredPos, cb, type)
    if not strNode or not redParGo then
        return
    end

    local filters = {
        Constants.RedPointConst.Welfare,
        Constants.RedPointConst.Task,
        Constants.RedPointConst.Other,
        Constants.RedPointConst.BattlePass,
        Constants.RedPointConst.OverseaStore,
        Constants.RedPointConst.Activity,
    }

    ---@type RedPointMgrComponent
    local redPointCom = GameUtils.GetEntityCompByType(ECSComponentType.Constants.RedPointMgrComponent)
    local redPointGo
    redPointCom:SetNodeCallBack(strNode, function(node)
        local unLock = true
        if table.find(filters, function(filter) return filter == strNode end) then
            unLock = GameUtils.IsUnlockedSingle(Constants.CommonUnlockType.PassQuest,101090)
        end
        if not unLock then
            return
        end
        if cb then
            cb(node)
        else
            if checkNumber(type) == Constants.RedPointType.COMMON then
                redPointGo = GameUtils.GetRedPointGo(redParGo)
            elseif checkNumber(type) == Constants.RedPointType.NEW then
                redPointGo = GameUtils.GetRedPointNewGo(redParGo)
            end

            if redPointGo then
                KTool.SetActive(redPointGo, node.pointNum > 0)
                if anchoredPos then
                    redPointGo.transform:GetComponent(typeof(RectTransform)).anchoredPosition = anchoredPos
                end
                --redPointGo.transform:GetComponent(typeof(RectTransform)).anchoredPosition = Vector2(0, 0)
            end
        end
    end)

    if isInvoke then
        redPointCom:InvokeCallBack(strNode)
    end

    --返回小红点go  方便修改位置
    return redPointGo
end

--找小红点  如果没有创建
function GameUtils.GetRedPointGo(redParGo, pos)
    if IsNull(redParGo) then
