    local redPointGo = redParGo.transform:Find("redPoint")
    if isNull(redPointGo) then
        local loader = ResourceModule.LoadBundleSync('Prefabs/Common/CommonRedPoint.prefab', nil, true)
        if loader.IsSuccess then
            redPointGo = loader:Instantiate(redParGo.transform, false)
