--- 检测 时间格式 末尾是否需要追加UTC标识（例如：xxxx-xx-xx(UTC+8)）
---@param originTimeFormat string
---@return string
function GameUtils.CheckUTCTimeformat(originTimeFormat)
    if GameUtils.isZmFunction() then
        local playerDojo = GameUtils.GetPlayerDojo()
        local serverTimezone = playerDojo:GetServerTimezone()
        local timezoneHours = serverTimezone / 3600
        local timezoneText = timezoneHours >= 0 and string.format('+%d', timezoneHours) or string.format('%d', timezoneHours)
        return string.fmt("%1 (UTC%2)", tostring(originTimeFormat), timezoneText)
    end
    return originTimeFormat
end
function GameUtils.GetUTCTimeZoneText()
    local str = ''
    if GameUtils.isZmFunction() then
        local playerDojo     = GameUtils.GetPlayerDojo()
        local serverTimezone = playerDojo:GetServerTimezone()
        local timezoneHours  = serverTimezone / 3600
        local timezoneText   = timezoneHours >= 0 and string.format('+%d', timezoneHours) or string.format('-%d', timezoneHours)
        str = string.fmt("(UTC%1)", timezoneText)
    end
    return str
end

function GameUtils.l10nTimeData(timeFormat, timestamp)
    local format = tostring(timeFormat or '!%Y-%m-%d %H:%M:%S')
    local playerDojo = GameUtils.GetPlayerDojo()
    return os.date(format, timestamp + playerDojo:GetServerTimezone() - playerDojo:GetClientTimezone())
end

