--- 刷新复用列表的数据
---@param scrollView SuperScrollView.LoopListView2 | SuperScrollView.LoopGridView
---@param len number
---@param resetPos boolean -- !!!! 注意, 目前这版函数中的参数 resetPos 是失效的, 无法传入 false; 此时可先改用下方的 ReloadData_Repaired()
function GameUtils.ReloadData(scrollView, len, resetPos)
    if not isNull(scrollView) then
        if not len or scrollView.ItemTotalCount == checkNumber(len) then
            scrollView:RefreshAllShownItem()
        else
            if resetPos then
                scrollView:SetListItemCount(checkNumber(len), resetPos)
            else
                scrollView:SetListItemCount(checkNumber(len))
            end

            --如果是LoopGridView set完之后都要调用一次刷新
            if iskindof(scrollView, typeof(CS.SuperScrollView.LoopGridView)) then

                -- 已经修复了 gridView 重新分配 itemCount 后，只更新增量的cell问题。
                -- 所以这里也就没有必要再次调用刷新全部了，拿新版增加的方法做一个版本环境判断
                -- TODO：不要放开，会有bug的，因为其他界面已经按照不刷新的方式取做了，开启会额外产生刷新
                if isNull(scrollView.UpdateDisplayItemCount) then
                    scrollView:RefreshAllShownItem()
                end

                -- 如果这里不重置一下的话，保持原地位置反复进出界面，会发现这个列表一直累计偏移值，导致越来越越偏
                scrollView.ContainerTrans.anchoredPosition3D = Vector3(0, 0, 0)
                scrollView:VaildAndSetContainerPos()
            end
        end
    end
end


-- 修复了上面 GameUtils.ReloadData() 参数resetPos 的问题;
function GameUtils.ReloadData_Repaired(scrollView, len, resetPos)
    if not isNull(scrollView) then
        if not len or scrollView.ItemTotalCount == checkNumber(len) then
            scrollView:RefreshAllShownItem()
        else
            if isNotNull(resetPos) and type(resetPos) == "boolean" then
                scrollView:SetListItemCount(checkNumber(len), resetPos)
            else
                scrollView:SetListItemCount(checkNumber(len))
            end

            --如果是LoopGridView set完之后都要调用一次刷新
            if iskindof(scrollView, typeof(CS.SuperScrollView.LoopGridView)) then

                -- 已经修复了 gridView 重新分配 itemCount 后，只更新增量的cell问题。
                -- 所以这里也就没有必要再次调用刷新全部了，拿新版增加的方法做一个版本环境判断
                -- TODO：不要放开，会有bug的，因为其他界面已经按照不刷新的方式取做了，开启会额外产生刷新
                if isNull(scrollView.UpdateDisplayItemCount) then
                    scrollView:RefreshAllShownItem()
                end

                -- 如果这里不重置一下的话，保持原地位置反复进出界面，会发现这个列表一直累计偏移值，导致越来越越偏
                scrollView.ContainerTrans.anchoredPosition3D = Vector3(0, 0, 0)
                scrollView:VaildAndSetContainerPos()
            end
        end
    end
end


--- 重置容器的节点数
---@param parentNode UnityEngine.RectTransform
---@param childNode UnityEngine.RectTransform
---@param childCount integer
---@param eachCallback fun(luaIndex:integer, childNode:UnityEngine.RectTransform):void | nil
function GameUtils.ResizeContent(parentNode, childNode, childCount, eachCallback)
    if isNull(parentNode) or isNull(childNode) then
        return
    end
    local originCnt = parentNode.childCount
    local minusCnt = childCount - originCnt
    if minusCnt < 0 then
        -- 隐藏多余的
        for index = originCnt, originCnt - math.abs(minusCnt) + 1, -1 do
            CfUtils.SetActive(parentNode:GetChild(index - 1), false)
        end
    elseif minusCnt > 0 then
        -- 补充不足的
        for index = 1, minusCnt do
            GameObject.Instantiate(childNode.gameObject, parentNode)
        end
    end
    -- 激活全部
    for index = 1, childCount do
        CfUtils.SetActive(parentNode:GetChild(index - 1), true)
        if eachCallback then
            local childObj = parentNode:GetChild(index - 1)
            eachCallback(index, childObj:GetComponent(typeof(RectTransform)))
        end
    end
end

---PlayAndWaitForAnim
---播放并且等待动画完成
---@param target UnityEngine.GameObject
---@param clipName string
---@param callback fun():void
---@param blockerConditionName string
function GameUtils.PlayAndWaitForAnim(target, clipName, callback, blockerConditionName)
    local anim = target:GetComponent(typeof(CS.UnityEngine.Animation))
    if anim == nil then
        if callback then
            callback()
        end
        return
    end
    if blockerConditionName then
        blocker:AddCondition(blockerConditionName)
    end
    anim:Play(clipName)
    CS.Engine.Lib.CoWait.Start():Until(function()
        return not anim:IsPlaying(clipName)
    end
    ) :Next(
            function()
                if callback then
                    callback()
                end
                if blockerConditionName then
                    blocker:RemoveCondition(blockerConditionName)
                end
            end
    )
end

---全屏窗口关闭后，之前如果有让底下窗口关闭显示的，现在恢复回来
function GameUtils.ShowPreviousDialogs()
    local dialogs = UIModule.CurrentScreen.dialogs
    local dialogsCount = dialogs.Count

    for i = 0, dialogs.Count - 1 do
        dialogs[i].CacheCanvas.enabled = true
    end
end

---新全屏窗口打开后，支持关闭底下看不见的窗口
function GameUtils.HidePreviousDialogs(currentDialog)
    if currentDialog == nil then
        return
    end

    local dialogs = UIModule.CurrentScreen.dialogs
    local dialogsCount = dialogs.Count
    local isHide = dialogsCount > 1
    if not isHide then
        return
    end

    for i = 0, dialogs.Count - 1 do
        if dialogs[i] == currentDialog then
            break
        end

        dialogs[i].CacheCanvas.enabled = false
    end
end

