---CloseDialog2AppointDialog
---关闭显示的弹窗到指定弹窗
---@param dialogId Constants.UITypeIds @ 指定的弹窗id
---@param isRemoveRecord boolean 是否清除记录 warn:默认清除
function GameUtils.CloseDialog2AppointDialog(dialogId, rootDialogId, isRemoveRecord)
    if isNull(UIModule.CurrentScreen) then
        return
    end
    if isRemoveRecord == nil then
        isRemoveRecord = true
    end
    return cs_coroutine.start(function()
        local dialogs = UIModule.CurrentScreen.dialogs
        for i = dialogs.Count, 1, -1 do
            local dialog = dialogs[i - 1]
            local id = dialog.Argument.id
            --- 未到根弹窗之前如果发现 要去的弹窗 则退出循环
            if id ~= rootDialogId then
                if id == dialogId then
                    break
                end
                cs_coroutine.yield_return(UIModule.CloseDialog(dialog, isRemoveRecord))
            else
                break
            end
        end
    end)
end

