function GameUtils.GetScreenData(originData, groups, filterClass, extraParams, screenDataSpecifyDic)
    local data
    local UIFilterType = Constants.UIFilterType
    if filterClass == UIFilterType.Card then
        ---@type CardProgressionUtils
        local CardProgressionUtils = import("Game.CardProgression.CardProgressionUtils")
        data = CardProgressionUtils.ScreenCards(originData, groups)
    elseif filterClass == UIFilterType.Equip then
        data = EquipUtils.ScreenEquip(originData, groups, extraParams)
    elseif filterClass == UIFilterType.EquipCultivate or filterClass == UIFilterType.EquipCultivateFastSelect then
        data = EquipUtils.ScreenEquipCultivate(originData, groups, extraParams, filterClass)
    elseif filterClass == UIFilterType.EquipReclaimFastSelect then
        data = EquipUtils.ScreenEquipReclaimFastSelect(originData, groups, extraParams)
    elseif filterClass == UIFilterType.CatHouse then
        ---@type CatHouseMgr
        local CatHouseMgr = import('Game.CatHouse.CatHouseMgr')
        return CatHouseMgr:GetInstance():ScreenCat(originData, groups, screenDataSpecifyDic)
    elseif filterClass == UIFilterType.MaterialCraft then
        data = GameUtils.ScreenMaterialCraft(originData, groups)
    elseif filterClass == UIFilterType.MaterialConvert then
        data = GameUtils.ScreenMaterialConvert(originData, groups)
    elseif filterClass == UIFilterType.CatBallCultivate or filterClass == UIFilterType.CatBallFight or UIFilterType.CatBallOperates then
        ---@type CatBallUtils
        local CatBallUtils = import("Game.CatBall.CatBallUtils")
        data = CatBallUtils.ScreenCatBall(originData, groups, filterClass)
    elseif filterClass == UIFilterType.ClubRecord then
        data = clone(originData)
    else
        data = clone(originData)
    end
    return data
end

