---CommonScreenBlack
---@param isShowIn boolean
---@param isShowOut boolean
---@param idleDuring number
---@param cb fun():void
---@param color string
---@param before function
function GameUtils.CommonScreenBlack(isShowIn, isShowOut, idleDuring, cb, color, before)
    local coShow = cs_coroutine.start(function()
        ---@type Engine.Modules.AbstractResourceLoader
        local loader = ResourceModule.LoadBundleAsync("Prefabs/Common/CommonScreenBlack.prefab", nil, true)
        while not loader.IsSuccess do
            cs_coroutine.yield_return(Yielders.EndOfFrame)
        end
        if loader.IsSuccess then
            local parent = GameUtils.GetUITopCanvas()
            if parent == nil then
                parent = UIModule.RootCanvas.transform
            end
            local go = loader:Instantiate()
            go.name = "CommonScreenBlack"
            if not KTool.IsNull(go) and not KTool.IsNull(parent) then
                local t = go:GetComponent(typeof(RectTransform))
                t:SetParent(parent)
                t.anchorMin = Vector2.zero
                t.anchorMax = Vector2.one
                t.offsetMin = Vector2.zero
                t.offsetMax = Vector2.zero
                t.localPosition = Vector3.zero
                t.localRotation = Quaternion.identity
                t.localScale = Vector3.one
                go.layer = parent.gameObject.layer
                ---获取lua脚本然后执行方法
                local PathCommonScreenBlack = "Game.Behaviours.CommonScreenBlack"
                local commonScreenBlack = GetLuaBehaviour(go, PathCommonScreenBlack)
                if not KTool.IsNull(commonScreenBlack) then
                    -- commonScreenBlack.Env.loader = loader
                    if before then
                        before()
                    end
                    ---执行逻辑
                    cs_coroutine.yield_return(commonScreenBlack.Env:ShowSequence(isShowIn, isShowOut, idleDuring, cb, color))
                end
            end
        end
        loader:Release(true)
    end)
    return coShow
end

