local SCREEN_SHOT_FILE = 'screen_shot.jpg'
local SCREEN_SHOT_HEIGHT = 1080
local SCREEN_SHOT_QUAILY = 75

---@param shareParms table @ 分享参数
---{
--- prefabPath       string     @ 分享内容的prefab路径（可选）
--- prefabArgs       table      @ 分享内容prefab的参数（可选）
--- fileName         string     @ 分享图片的名字（可选，默认 screen_shot.jpg）
--- imgQuaily        integer    @ 图片质量，范围1-100（可选，默认 75）
--- finishCB         fun(filePath:string):void @ 截图完成回调
--- camera3dData     table      @ 3d相机的参数（可选，默认为空）{ cameraGo:UnityEngine.Camera, beforeCM:integer, afterCM:integer}
--- isWaitCompleted  bool       @ 是否在初始化流程完整走完后再截图
---}
function GameUtils.ShareScreenShot(shareParms)
    local mainCanvas = UIRootCanvas.main.canvas
    local shareParms = checkTable(shareParms)

    -- append share prefab
    ---@type UnityEngine.GameObject
    local prefabGObj = nil
    local prefabLEnv = nil
    local prefabPath = shareParms.prefabPath
    local prefabArgs = shareParms.prefabArgs

    local execute = function()
        cs_coroutine.start(function()
            -- 隐藏水印
            GameUtils.SwitchWaterMark(false)

            -- switch uiCamera cullingMask
            local uiCamera = UIModule.RootCanvas.defaultCamera
            local origMask = uiCamera.cullingMask
            uiCamera.cullingMask = LayerMask.GetMask("UI_share", "UI_scene")

            ---@type UnityEngine.Camera
            local camera3dGo = nil
            -- switch 3dCamera cullingMask
            if shareParms.camera3dData and shareParms.camera3dData.cameraGo then
                camera3dGo = shareParms.camera3dData.cameraGo
                camera3dGo.cullingMask = shareParms.camera3dData.afterCM
            end

            -- hide touchEffect
            -- ScreenTouchEffectModule:Hide()  -- 怀疑此方法有bug，隐藏不掉

            -- save screen shot
            local fileName = shareParms.fileName or SCREEN_SHOT_FILE
            local imgScale = math.min(SCREEN_SHOT_HEIGHT / Screen.height, 1)
            local imgQuaily = shareParms.imgQuaily or SCREEN_SHOT_QUAILY
            local filePath = GameUtils.GetShareScreenPath(fileName)
            local shotSize = Vector2(Screen.width * imgScale, Screen.height * imgScale)
            if Screen.height <= SCREEN_SHOT_HEIGHT then
                -- 当分辨率小于等于1080时，尺寸设为空。
                -- 因为不需要缩放是，应该避免 c#层调用 ScaleBilinear 方法，造成不必要的重绘开销
                shotSize = Vector2(0, 0)
            end
            cs_coroutine.yield_return(TextureUtility.SaveScreenShot(filePath, shotSize, imgQuaily))
            print('[share SaveScreenShot]', filePath)

            -- show touchEffect
            -- reset uiCamera cullingMask
            uiCamera.cullingMask = origMask

            -- reset 3dCamera cullingMask
            if camera3dGo then
                camera3dGo.cullingMask = shareParms.camera3dData.beforeCM
            end

            -- finish callback
            if shareParms.finishCB then
                CoYield(shareParms.finishCB(filePath))
            end

            -- delete share prefab
            CfUtils.SetActive(prefabGObj, false)
            CfUtils.SafeDelete(prefabGObj, true)

            -- 等本帧的删除执行结束，再执行后面的 finishCB。
            -- 因为回调里面会打开接分享预览界面，不等带删除就立刻打开的话，会被分享预览界面里的背景截屏截到未销毁的内容页
            -- coroutine.yield(Yielders.EndOfFrame)  -- finishCB 放在先执行，就不用这里等待了

            KTool.SetActive(ScreenTouchEffectModule, true)
            CS.Engine.UI.UIRaycastBlocker.Instance:RemoveCondition("CommonSharePreviewDialog")

            -- 恢复水印
            GameUtils.SwitchWaterMark(true)
        end)
    end

    KTool.SetActive(ScreenTouchEffectModule, false)
    CS.Engine.UI.UIRaycastBlocker.Instance:AddCondition("CommonSharePreviewDialog")

    if prefabPath then
        prefabGObj = GameUtils.LoadBundleSync(prefabPath, mainCanvas)
        local luaComp = KTool.GetComponent(prefabGObj, typeof(LuaBehaviour))
        prefabLEnv = not isNull(luaComp) and luaComp.Env or nil
        if not isNull(prefabLEnv) then
            if shareParms.isWaitCompleted and prefabLEnv.SetInitCompleteCB then
                prefabLEnv:SetInitCompleteCB(execute)
            end
            if prefabLEnv.OnInit then
                prefabLEnv:OnInit(prefabArgs)
            end
        end
    end
    if not shareParms.isWaitCompleted then
        execute()
    end
end

