function GameUtils.GetWinUserCenterUrl(channelId, access_token, loginType, role_name, app_name, agreement_user_version, uid)
    channelId = checkString(channelId)
    local url = WinConfig.UserCenter[channelId]
    if isNull(url) then
        return ""
    end
    local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
    if isNull(userComponent) then
        return ""
    end

    local userInfo = userComponent.userInfo
    if isNull(userInfo) then
        return ""
    end

    local webLoginMsg = checkTable(CfUtils.CookieLoad('WebLoginMsg'))
    url = string.fmt(url, {
        _lang_                   = CS.Engine.I18N.I18NModule.Lang,
        _accesstoken_            = access_token,
        _role_name_              = role_name,
        _uid_                    = uid,
        _channel_                = GameUtils.GetChannelId(),
        _server_                 = userInfo.serverId,
        _app_name_               = app_name,
        _appId_                  = GameUtils.GetCurAppId(),
        _loginType_              = loginType,
        _agreement_user_version_ = agreement_user_version,
        _user_id_                = webLoginMsg.user_id,
    })
    print(url)
    return url
end

