--- 加载spine动画 (使用缓存的页面要自己释放缓存里的gameobject)
---@param resPath string 预制体路径
---@param outData table 返回加载好的skeletonDataAsset
---@return UnityEngine.Coroutine 加载协程
function GameUtils.GetSpineEmojiData(resPath, outData, useCache, cacheList)
    local co = cs_coroutine.start(function()
        if useCache then
            if isSet(cacheList, resPath) then
                local go = cacheList[resPath]
                local sgComp = go:GetComponent(typeof(SkeletonGraphic))
                outData.skeletonDataAsset = sgComp.skeletonDataAsset
                return
            end
        end

        local loader = ResourceModule.LoadBundleAsync(resPath, nil, true)
        while not loader.IsSuccess do
            cs_coroutine.yield_return()
        end
        if not loader.IsError then
            local go = loader:Instantiate()
            -- go.hideFlags = CS.UnityEngine.HideFlags.HideInHierarchy

            if useCache then
                cacheList[resPath] = go
            end

            local sgComp = go:GetComponent(typeof(SkeletonGraphic))
            outData.skeletonDataAsset = sgComp.skeletonDataAsset
        end
        loader:Release()
        loader = nil
    end)

    return co
end
