---WriteFile
---写入一个文件
---
function GameUtils.WriteFile(writePath, _str, mode)

    local path = CS.UnityEngine.Application.persistentDataPath
    function subString(str, k)
        local ts = string.reverse(str)
        local _, i = string.find(ts, k)
        local m = string.len(ts) - i + 1
        return string.sub(str, 1, m)
    end

    if CS.UnityEngine.Application.isEditor then
        path = CS.UnityEngine.Application.dataPath
        path = subString(path, "/") .. string.format("Product/%s", writePath)
    else
        path = path .. "/" .. writePath
    end
    --写
    local str = string.format("\n%s : %s", os.date("%m.%d %H:%M:%S", os.time()), _str)
    io.writeFile(path, str, mode)
end

