function GameUtils.ScreenMaterialCraft(originData, groups)
    if next(groups) == nil then
        return clone(originData)
    end

    local data = {}
    for _, v in ipairs(originData) do
        local canInsert = false
        local goodsId = checkInt(v.gainId)
        for _, type in ipairs(groups[Constants.ScreenType.MaterialCraft]) do
            if type == Constants.MaterialCraftItemType.MODULE then
                if goodsId >= 4102101 and goodsId <= 4102506 then
                    canInsert = true
                    break
                end
            elseif type == Constants.MaterialCraftItemType.PARTICLE then
                if goodsId >= 4102011 and goodsId <= 4102031 then
                    canInsert = true
                    break
                end
            elseif type == Constants.MaterialCraftItemType.FIBRE then
                if goodsId >= 4100022 and goodsId <= 4100026 then
                    canInsert = true
                    break
                end
            end
        end
        if canInsert then
            table.insert(data, v)
        end
    end
    return data
end

