---将活动时间中的剩余秒数转换为时间戳
---@param activityData table 活动数据
function GameUtils.ConventSecondToTimeStamp(activityData)
    if not activityData then
        return
    end
    ---@type PlayerComponent
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    if not comp then
        return
    end
    local curTime = comp:GetPlayerDojo():GetServerTime()
    curTime = curTime or os.time()
    for _, activityDt in pairs(checkTable(activityData)) do
        if activityDt.startTime then
            activityDt.startTime = activityDt.startTime + curTime
        end
        if activityDt.endTime then
            activityDt.endTime = activityDt.endTime + curTime
        end
        if activityDt.closeTime then
            activityDt.closeTime = activityDt.closeTime + curTime
        end
    end
end

function GameUtils.ConventSingleSecondToTimeStamp(activityDt, curTime)
    if not activityDt then
        return
    end
    if curTime == nil then
        curTime = GameUtils.GetServerTime() or os.time()
    end
    if activityDt.startTime then
        activityDt.startTime = activityDt.startTime + curTime
    end
    if activityDt.endTime then
        activityDt.endTime = activityDt.endTime + curTime
    end
    if activityDt.closeTime then
        activityDt.closeTime = activityDt.closeTime + curTime
    end
end

function GameUtils.ToTimeStamp(deltaSeconds, curTime)
    if curTime == nil then
        curTime = GameUtils.GetServerTime() or os.time()
    end
    return checkNumber(deltaSeconds) + curTime
end

--- 字符串替换
---@param s string 原始字符串
---@param pattern string 匹配模式
---@param replace string 替换字符串
function GameUtils.ReplaceStr(s, pattern, replace)
    if string.isEmpty(s) then
        return s
    end
    local i, j = string.find(s, pattern, 1, true)
    if i and j then
        local ret = {}
        local start = 1
        while i and j do
            table.insert(ret, string.sub(s, start, i - 1))
            table.insert(ret, replace)
            start = j + 1
            i, j = string.find(s, pattern, start, true)
        end
        table.insert(ret, string.sub(s, start))
        return table.concat(ret)
    end
    return s
end

