--- 道具飞入顶部货币栏动画
---@param startGo UnityEngine.GameObject
---@param goodsId integer
---@param isMore boolean | nil @ 是普通量的效果，还是大量的效果。default false
---@param targetCallback fun():void | nil @ 动画飞到目的地回调
---@return UnityEngine.Coroutine
function GameUtils.StartFlyGoods(startGo, goodsId, isMore, targetCallback)
    local co = cs_coroutine.start(function()
        CS.Engine.UI.UIRaycastBlocker.Instance:AddCondition("StartGoodsFly")
        ---@type UnityEngine.RectTransform
        local iconNode = GameUtils.GetIcon(goodsId)
        local parent = startGo.gameObject
        local boomLoader = ResourceModule.LoadBundleAsync(DynamicLoadEffectPath.Boom, nil, true)
        local boomMoveLoader = ResourceModule.LoadBundleAsync(DynamicLoadEffectPath.BoomMove, nil, true)
        local boomBoom2Loader = ResourceModule.LoadBundleAsync(DynamicLoadEffectPath.BoomBoom2, nil, true)
        local tex = GameUtils.LoadMatTexture(goodsId)
        while not boomLoader.IsCompleted or not boomMoveLoader.IsCompleted do
            cs_coroutine.yield_return(Yielders.EndOfFrame)
        end
        local boomGo = GameUtils.InstantiateGoByLoader(boomLoader, parent)
        local boomMoveGo = GameUtils.InstantiateGoByLoader(boomMoveLoader, parent)
        local iconPosition = iconNode and iconNode.transform.position or parent -- 做一个容错，找不到顶部货币栏就原地播放
        local name = isMore and "UIFX_MoreGoodsImgChange" or "UIFX_GoodsImgChange"
        local effectGo = boomMoveGo.transform:Find(name)
        local render
        if not isNull(effectGo) then
            render = effectGo:GetComponent(typeof(CS.UnityEngine.Renderer))
            if not isNull(render) then
                local id = CS.UnityEngine.Shader.PropertyToID("_MainTex")
                render.material:SetTexture(id, tex)
            end
        end

        ---@type Engine.UI.ParticleTargetMove
        local particleTargetMove = KTool.GetComponent(effectGo.gameObject, typeof(CS.Engine.UI.ParticleTargetMove))
        if not isNull(particleTargetMove) then
            particleTargetMove:Play(iconPosition)
        end
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(particleTargetMove.delayTime))

        while not boomBoom2Loader.IsCompleted do
            cs_coroutine.yield_return(Yielders.EndOfFrame)
        end
        KTool.SafeDelete(boomGo)
        KTool.SafeDelete(boomMoveGo)
        if targetCallback then
            targetCallback()
        end

        local boomBoom2Go = GameUtils.InstantiateGoByLoader(boomBoom2Loader, parent)
        boomBoom2Go.transform.position = iconPosition
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.5))
        KTool.SafeDelete(boomBoom2Go)
        CS.Engine.UI.UIRaycastBlocker.Instance:RemoveCondition("StartGoodsFly")
    end)
    return co
end

