--- 显示一个剧情的回看界面  因为是从剧情那边剥离出来的 所以没做删除 要自己到beforeClose里面处理删除对象本身
---@param record table 剧情数据
---@param order integer 界面层级
---@param afterStart function 打开回调
---@param beforeClose function 关闭回调
function GameUtils.ShowChapterReview(record, order, afterStart, beforeClose)
    ---@type Engine.Modules.AbstractResourceLoader
    local loader = ResourceModule.LoadBundleSync("Prefabs/Chapter/ChapterReviewPopup.prefab")
    while not loader.IsSuccess do
        cs_coroutine.yield_return(Yielders.EndOfFrame)
    end
    if loader.IsSuccess then
        local go = loader:Instantiate(UIModule.RootCanvas.transform, false)
        loader:Release()

        go.name = "ChapterReviewPopup"
        if not KTool.IsNull(go) and not KTool.IsNull(UIModule.RootCanvas.gameObject) then
            local t = go:GetComponent(typeof(RectTransform))
            t.anchorMin = Vector2.zero
            t.anchorMax = Vector2.one
            t.offsetMin = Vector2.zero
            t.offsetMax = Vector2.zero
            t.localPosition = Vector3.zero
            t.localRotation = Quaternion.identity
            t.localScale = Vector3.one
            go.layer = UIModule.RootCanvas.gameObject.layer

            ---有的剧情下面有返回按钮 要比返回按钮的层级高
            local orderTracker = KTool.GetOrAddComponent(go.gameObject, typeof(CS.Engine.UI.OrderTracker))
            if isNotNull(orderTracker) then
                orderTracker.addSortingOrder = order or 1010
            end

            ---获取lua脚本然后执行方法
            local reviewEnv = CfUtils.GetLuaScr(go, "Game.Chapter.NewChapterReview")
            if not KTool.IsNull(reviewEnv) then
                reviewEnv:Show(record, afterStart, beforeClose)
            end
        end
    else
        loader:Release(true)
    end
end

--- 列表分页
---@param rawTable table 原始列表
---@param oneCount number 每页的数量
function GameUtils.SplitTable(rawTable, oneCount)
    local newTable = {}
    local index = 0
    local count = oneCount
    for i, v in pairs(rawTable) do
        if count >= oneCount then
            count = 0
            index = index + 1
            newTable[index] = {}
        end
        table.insert(newTable[index], v)
        count = count + 1
    end
    return newTable
end

