---是否限制当前卡牌上阵
function GameUtils.IsLimitCard(questId, cardId, teamIndex)
    if isNull(questId) or isNull(cardId) then
        return false
    end
    local levelType = GoodsUtils.GetIdType(questId, Constants.IDArea.Quests)
    if not isNull(levelType) then
        if levelType == Constants.IDType.ClubBoss then
            return ClubUtils.IsBossLimitCard(cardId)
        elseif levelType == Constants.IDType.QuestChaoticRecall then
            local ChaoticRecallUtils = import("Game.UI.FightReady.ChaoticRecall.ChaoticRecallUtils")
            return ChaoticRecallUtils.IsLimitCard(questId, cardId, teamIndex)
        elseif levelType == Constants.IDType.Fairyland then
            local FairylandUtils = import("Game.Fairyland.FairylandUtils")
            return FairylandUtils.IsLimitCard(FairylandUtils.CurrentEnterQuestId, cardId)
        end
    end
    return false
end

---是否限制当前猫球上阵
function GameUtils.IsLimitCat(questId, catId, teamIndex)
    if isNull(questId) or isNull(catId) then
        return false
    end
    local levelType = GoodsUtils.GetIdType(questId, Constants.IDArea.Quests)
    if not isNull(levelType) then
        if levelType == Constants.IDType.ClubBoss then
            return ClubUtils.IsBossLimitCat(catId)
        elseif levelType == Constants.IDType.QuestChaoticRecall then
            local ChaoticRecallUtils = import("Game.UI.FightReady.ChaoticRecall.ChaoticRecallUtils")
            return ChaoticRecallUtils.IsLimitCat(questId, catId, teamIndex)
        elseif levelType == Constants.IDType.Fairyland then
            local FairylandUtils = import("Game.Fairyland.FairylandUtils")
            return FairylandUtils.IsLimitCat(FairylandUtils.CurrentEnterQuestId, catId)
        end
    end
    return false
end

