end

--- 刷新情绪共鸣节点
---@param node any
---@param teams any
---@param canClick any
---@param showDetail any
---@param refreshFX boolean 刷新特效
function GameUtils.RefreshLineupBonusNode(node, teams, canClick, showDetail, refreshFX)
    if CardUtils.IsEmotionBonusOpened() then
        ---@type UIFightTeamLineupBonusNode
        local lt = GetLuaBehaviour(node.gameObject, "Game.UI.FightTeam.UIFightTeamLineupBonus.UIFightTeamLineupBonusNode").Env

        local unlocked, desc = CardUtils.IsEmotionBonusUnlocked()
        lt:SetLocked(not unlocked, desc)
        if unlocked then
            lt:SetCanClick(canClick)
            lt:SetShowDetail(showDetail)
            lt:SetRefreshFX(refreshFX)
            lt:RefreshLineup(teams)
        else
            lt:SetCanClick(false)
            lt:Refresh()
        end
    else
        KTool.SetActive(node, false)
    end
end

function GameUtils.RefreshCommonRoleUpShow(node, data, callBack, excludeDialogs)
