--- 隐藏全部子节点
---@param parent any
function GameUtils.HideAllChild(parent, name)
    if isNull(parent) then
        return
    end
    local transform = parent.transform

    -- 隐藏原名的go
    if not string.isEmpty(name) then
        local child = transform:Find(name)
        if isNotNull(child) then
            KTool.SetActive(child, false)
        end
    end

    -- 隐藏原名带后缀的go
    local childCount = transform.childCount
    for i = 0, childCount - 1, 1 do
        local child = nil
        if string.isEmpty(name) then
            child = transform:GetChild(i)
        else
            child = transform:Find(name .. (i + 1))
        end
        if isNotNull(child) then
            KTool.SetActive(child, false)
        end
    end
end

--- 根据数据刷新子节点
---@param data any
---@param root any
---@param cell any
---@param cellName any
---@param cellLuaPath any
function GameUtils.RefreshAllChild(data, root, cell, cellName, cellLuaPath)
    if isNull(data) then
        return
    end
    cellName = cellName or "Cell"
    root = root.transform
    local count = table.count(data)
    for i = 1, count, 1 do
        local node = root:Find(cellName .. i)
        if isNull(node) then
            node = KTool.Instantiate(root.gameObject, cell.gameObject)
            node.name = cellName .. i
        end
        node = node.gameObject
        KTool.SetActive(node, true)
        local lb = GetLuaBehaviour(node, cellLuaPath)
        if isNotNull(lb) then
            lb.Env:Refresh(data[i], i)
        end
    end
end

--- 计算战中加成属性的全局天赋加成id
---@param attrAddId any
function GameUtils.CalculateBattleAttrTalentEffectId(attrAddId)
    -- Constants.GlobalTalentEffectId.Id_10101
    local talentId = Constants.GlobalTalentEffectId
    local prefix = 'Id_'
    local effectId = 10000 + attrAddId
    local finalId = prefix .. effectId
    return Constants.GlobalTalentEffectId[finalId]
end

