function GameUtils.CalculateCostNumWithTalentAddition(questVo, costNum)
    local levelType = checkNumber(questVo.levelType)
    local targetParam3 = nil
    if levelType == Constants.RegionSecondQuestType.Exp then
        local dailyType = checkNumber(questVo.type)     -- 日常材料副本的类型
        targetParam3 = dailyType
    elseif levelType == Constants.RegionSecondQuestType.Equip then
        local pointId = checkNumber(questVo.pointID)    -- 关卡所属二级区域地图id
        local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
        local mapVo = ActionUtils.GetRegionSecondaryMapVo(pointId)
        targetParam3 = checkNumber(mapVo.regionBelong)
    end
    local globalTalentMgr = GlobalTalentMgr:GetInstance()
    local costNum = globalTalentMgr:CalcNum(costNum, Constants.GlobalTalentEffectId.Id_14, false, function(data)
        -- "参数1：系统功能ID（默认2001：包含装备 晶片 例子 经验 4个副本）
        -- 参数2：不同日常本（1装备本2食材本3Boss本4升阶材料本6经验本5粒子本)
        -- 参数3：若2是晶片本（4），则是不同颜色晶片本关卡ID；若2是装备本（1），则是区域ID；若2是经验本和粒子本，则空"
        ---@type HomelandTalentUpLvVo
        local vo        = data.vo
        local systemId  = vo.param1
        if systemId ~= Constants.SystemToggleIds.Id2001 then
            return false
        end

        local levelType_ = vo.param2
        if levelType_ ~= levelType then
            return false
        end

        if targetParam3 ~= nil then
            local param3 = vo.param3
            return param3 == targetParam3
        end

        return true
    end, true)

    return costNum
end

--- 判断是否是在主界面上
function GameUtils.IsInMainHomeView()
    local UIModule = CS.Engine.UI.UIModule
    local dialogs = UIModule.CurrentScreen.dialogs
    if isNull(dialogs) then
        return
    end

    local dialogsCount = dialogs.Count
    if dialogsCount == 1 then
        local dialog = dialogs[0]
        if isNotNull(dialog) then
            local dialogId = dialog.Argument.id
            if dialogId == Constants.UITypeIds.UIHomeView then
                return true
            end
        end
    end

    return false
end

--- 从服务器时区当天0点开始hour,min,sec后的时间戳
---@param hour any
---@param min any
---@param sec any
function GameUtils.GetServerTimeStamp(hour, min, sec)
    ---@type PlayerComponent
    local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    if not isNull(playerComp) then
        ---@type PlayerDojo
        local playerDojo = playerComp.playerDojo
        if checkInt(playerDojo.serverTime) <= 1000 then
            return os.time()
        end
        -- 服务器时间戳
        local serverTimeStamp = playerDojo:GetServerTime()
        -- 服务器时间戳 转成 客户端时区的time对象
        local tm = timestamp_to_time(serverTimeStamp)
        -- 服务器时区0点的时间戳
        local zeroTimeStamp = os.time({
            year = tm.year,
            month = tm.month,
            day = tm.day,
            hour = 0,
            min = 0,
            sec = 0 - playerDojo:GetServerTimezone() + playerDojo:GetClientTimezone(),
        })
        -- 处理时间跨天的情况（与服务器的当天相比）
        if zeroTimeStamp > serverTimeStamp then
            zeroTimeStamp = zeroTimeStamp - 86400
        elseif (serverTimeStamp - zeroTimeStamp) > 86400 then
            zeroTimeStamp = zeroTimeStamp + 86400
        end

        local timeStamp = zeroTimeStamp + (3600 * checkNumber(hour) + 60 * checkNumber(min) + checkNumber(sec))

        return timeStamp
    end

    return -1
end

