--- 重启战斗
function GameUtils.RestartBattle(questId, restartInBattle)
    local fightPreWarMgr = FightPreWarMgr:GetInstance()
    local args = fightPreWarMgr:GetBattleArgs()
    local battleEnterReqId, battleEnterReqBody, battleEndReqId, battleEndReqBody, battleEndCb = fightPreWarMgr:GetFightEnterArgs(questId, args)
    if not battleEnterReqId or not battleEndReqId then return end
    battleEnterReqBody.restartInBattle = restartInBattle  -- 标记是否是从战中未经结算就重启了战斗
    GameUtils.Request(battleEnterReqId, battleEnterReqBody, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            fightPreWarMgr:SetArgs(args)
            fightPreWarMgr:BattleEnterErrorHandle(questId)
            return
        end

        -- local comp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CookingComponent)
        -- --使用就扣除
        -- if comp:IsActiveBattleFood() then
        --     comp:DelUseBattleFoodTime(questId)
        -- end

        local responseData = checkTable(response.data)
        fightPreWarMgr:BattleBeforHandle(questId, responseData)
        responseData.isRecord = checkNumber(args.isRecord)
        --保存战斗数据
        fightPreWarMgr:SetFightData(responseData, args)
        --清掉当前所有的ui
        local dialogs = UIModule.CurrentScreen.dialogs
        for i, dialog in pairs(dialogs) do
            UIModule.CloseDialog(dialog)
        end
        if BattleEndMgr then
            BattleEndMgr:ResetCameraAndLight()
            -- 50皮结算会deactive场景，重启战斗要active一下
            BattleEndMgr:SetActiveBattleEndScene(true)
            -- 50皮结算会deactive阴影，重启战斗要active一下
            BattleEndMgr:SetActiveLowDiscShadow(true)
        end
        BattleMgr = import('Game.Battle.Core.BattleMgr')
        BattleViewMgr = import('Game.BattleView.Core.BattleViewMgr')
        BattleMgr.gameMode = Constants.GameMode.PVE
        BattleViewMgr.gameMode = Constants.GameMode.PVE
        BattleViewMgr:RestartBattle(checkTable(fightPreWarMgr:GetFightData().battleData))
        --BattleEndMgr:ResetSceneCamera()
    end)
end

function GameUtils.FillConsumePopUp(go,questVo,parametersVo,times,callBack)
    ---@type CommonFilter
    local lt = CfUtils.GetLuaScr(go.gameObject, "Game.UI.Common.CommonFilter")
    if isNotNull(lt) then
        CfUtils.SetActive(go, true)
        if questVo then
            local costItem = questVo.costItem
            local costNum = (questVo.costNum + questVo.costNumLose)
            ---@type GoodsVo
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(costItem)
            if isNull(goodsVo) then
                printError("id %s 找不到道具信息", costItem)
                return
            end
            
            local p = string.split(parametersVo.num, ";")
            -- 构造列表数据
            local filterData = {}
            for _i, v in ipairs(p) do
                local data = {
                    imgPath = goodsVo.photoPath,
                    text1 = localize("_num_倍", {_num_ = v}),
                    text2 = tostring(costNum * checkInt(v))
                }
                table.insert(filterData, data)
            end
            
            lt:SetOnValueChanged(callBack)
            lt:RefreshPanel(filterData, times)
        end
    end
end

return GameUtils
